  ('ffeec1c1-803f-56b3-aa0d-67f29b016f68'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Une nuit d’hospitalité devant le juge","competence":"analyser-texte","situation":"Dans une vallée de montagne, une habitante a hébergé un voyageur étranger sans papiers. Elle est poursuivie. Un lycéen suit l’affaire pour son exposé d’EMC.","documents":[{"id":"cas","type":"texte","genre":"article","titre":"Une habitante poursuivie","source":"Article écrit pour l’exercice : personnes et lieux imaginés","blocs":["Mme Roche, retraitée de Valbrune, a logé deux nuits un voyageur étranger dont le séjour n’était pas régulier. Elle l’a fait gratuitement, sans rien demander en échange.","Poursuivie pour avoir aidé un étranger en situation irrégulière, elle explique son geste en un mot : humanité.","Son avocat invoque le principe de fraternité, reconnu par le Conseil constitutionnel le 6 juillet 2018."]},{"id":"decision","type":"texte","genre":"source","titre":"Ce que tire le Conseil de la fraternité","source":"Texte adapté pour l’exercice, d’après la décision du 6 juillet 2018","blocs":["Le principe de fraternité implique la liberté d’aider autrui, dans un but humanitaire, sans considération de la régularité de son séjour sur le territoire."]}],"questions":[{"enonce":"Touche le mot par lequel Mme Roche résume pourquoi elle a agi.","aide":"Cherche le mot que le texte annonce après « en un mot ».","type":"zone","document":"cas","multiple":false},{"enonce":"D’après l’extrait de la décision, que protège la fraternité dans une telle situation ?","aide":"Relis la fin de la phrase de la décision : « sans considération… ».","type":"choix","options":[{"id":"a","texte":"L’interdiction de contrôler le séjour des étrangers sur l’ensemble du territoire"},{"id":"b","texte":"La liberté d’aider autrui dans un but humanitaire, quelle que soit la régularité de son séjour"},{"id":"c","texte":"Le droit de loger n’importe quel étranger en échange d’une somme d’argent"},{"id":"d","texte":"L’obligation pour l’État d’héberger toute personne qui en fait la demande"}],"multiple":false},{"enonce":"Complète le résumé de l’affaire.","aide":"La valeur dont parle l’avocat de Mme Roche est inscrite dans la devise de la République.","type":"trous","segments":["Le Conseil constitutionnel reconnaît à la ",0," une valeur ",1," ; le « délit de ",2," » se trouve limité."],"banque":["constitutionnelle","solidarité","égalité","législative","fraternité"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m45"]},"explication":"Elle invoque l’**humanité** : un motif désintéressé, et non un profit."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le Conseil reconnaît la **liberté d’aider autrui dans un but humanitaire**, sans considération de la régularité de son séjour. C’est ce qui limite le « délit de solidarité »."},{"cle":{"type":"trous","trous":[["fraternite"],["constitutionnelle"],["solidarite"]]},"affichage":"fraternité · constitutionnelle · solidarité","explication":"Le 6 juillet 2018, la **fraternité** reçoit une valeur **constitutionnelle** ; le « délit de **solidarité** » est limité pour l’aide désintéressée."}]$ex$::jsonb),
