  ('f528c350-34ff-546a-8dae-67ccca604594'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le niveau de vie médian de l’immeuble","competence":"lire-tableau","situation":"Dans un immeuble imaginaire, sept foyers comparent leur niveau de vie. Une élève veut comprendre ce que veulent dire « médian » et « seuil de pauvreté ».","documents":[{"id":"foyers","type":"tableau","titre":"Niveau de vie mensuel par personne","source":"Chiffres imaginés pour l’exercice, foyers classés du plus modeste au plus aisé","colonnes":["Foyer","Niveau de vie (€)"],"lignes":[["A",1200],["B",1400],["C",1500],["D",1800],["E",2000],["F",2200],["G",9000]],"enteteLignes":true}],"questions":[{"enonce":"Les foyers sont classés du plus modeste au plus aisé. Touche le niveau de vie médian, qui partage les sept foyers en deux moitiés.","aide":"Il y a trois foyers en dessous et trois au-dessus : cherche celui du milieu.","type":"zone","document":"foyers","multiple":false},{"enonce":"Le seuil de pauvreté est fixé à 60 % du niveau de vie médian. Quel est-il ici ?","aide":"Calcule 60 % de 1 800.","type":"nombre","unite":"€"},{"enonce":"Pourquoi la médiane décrit-elle mieux cet immeuble que la moyenne ?","aide":"Regarde le foyer G : que ferait-il à la moyenne ?","type":"choix","options":[{"id":"a","texte":"Parce que la moyenne ne tient pas compte des revenus les plus modestes"},{"id":"b","texte":"Parce que la moyenne est toujours plus faible que la médiane"},{"id":"c","texte":"Parce que la médiane ajoute tous les revenus puis les divise par sept"},{"id":"d","texte":"Parce qu’un seul très haut revenu fait monter la moyenne sans changer la médiane"}],"multiple":false}]}$ex$::jsonb,
