  ('2d2e06e1-de83-557f-bb3d-e6852dfd4774'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Lina et Hugo débattent de l’écart de salaire","competence":"lire-graphique","situation":"En classe, Lina et Hugo ne sont pas d’accord sur l’écart de rémunération entre femmes et hommes. Le graphique les départagera.","documents":[{"id":"ecart","type":"graphique","forme":"barres","titre":"Écart de revenu salarial entre femmes et hommes","source":"Chiffres arrondis","categories":["Tous temps de travail confondus","À poste et temps de travail comparables"],"series":[{"nom":"Écart","valeurs":[20,4],"teinte":"violet"}],"axeY":{"titre":"Écart","unite":"en %","min":0,"max":25,"pas":5},"axeX":{"titre":"Situation"}},{"id":"debat","type":"texte","genre":"source","titre":"Le débat de la classe","source":"Texte écrit pour l’exercice","blocs":["Lina : « Les femmes sont payées 20 % de moins pour le même travail. »","Hugo : « Cet écart n’existe pas : il vient uniquement du temps partiel. »"]}],"questions":[{"enonce":"Touche la barre qui mesure l’écart à poste et temps de travail comparables.","aide":"Lis les libellés sous les barres.","type":"zone","document":"ecart","multiple":false},{"enonce":"Quelle part de l’écart de 20 % est expliquée par les différences de poste et de temps de travail ?","aide":"Retire 4 à 20, puis compare le résultat à 20.","type":"nombre","unite":"%"},{"enonce":"Touche l’expression de Lina que le graphique ne confirme pas.","aide":"Compare ce que dit Lina à la barre de droite.","type":"zone","document":"debat","multiple":true},{"enonce":"Que peut-on répondre à Hugo ?","aide":"Regarde la barre de droite : est-elle à zéro ?","type":"choix","options":[{"id":"a","texte":"Il exagère : un écart d’environ 4 % subsiste à poste comparable"},{"id":"b","texte":"Il a raison : le graphique ne montre aucun écart de salaire"},{"id":"c","texte":"Il a raison : à poste comparable, l’écart est nul"},{"id":"d","texte":"Il a tort : l’écart n’a rien à voir avec le temps partiel"}],"multiple":false},{"enonce":"Associe chaque cause de l’écart à ce qu’elle recouvre.","aide":"Pense à un mot, un métier, une promotion.","type":"association","gauche":[{"id":"g0","texte":"Temps partiel"},{"id":"g1","texte":"Ségrégation professionnelle"},{"id":"g2","texte":"Plafond de verre"}],"droite":[{"id":"d0","texte":"Obstacles à l’accès aux postes de direction"},{"id":"d1","texte":"Très majoritairement féminin"},{"id":"d2","texte":"Des métiers très féminins, souvent moins rémunérés"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k1"]},"explication":"À poste et temps de travail comparables, l’écart est d’environ **4 %**."},{"cle":{"type":"nombre","valeur":80,"tolerance":0},"affichage":"80 %","explication":"20 − 4 = 16 points sur 20, soit **80 %** de l’écart. Les 4 points restants ne s’expliquent pas par le poste ou le temps."},{"cle":{"type":"zone","ids":["m10","m11"]},"explication":"À **même travail** (même poste, même temps), l’écart est d’environ 4 %, pas 20 %. L’écart de 20 % concerne tous les temps de travail confondus."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le temps partiel et les métiers expliquent l’essentiel, mais il reste **environ 4 %** d’écart à situation comparable."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"Temps partiel, **ségrégation professionnelle**, **plafond de verre** : trois causes qui expliquent l’écart de revenu sans être une inégalité de salaire à poste égal."}]$ex$::jsonb),
  ('2d2e06e1-de83-557f-bb3d-e6852dfd4774'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Égalité en droit, égalité réelle","competence":"analyser-document","situation":"La mairie de Saint-Aubin prépare une campagne sur l’égalité. Elle réunit une affiche sur les violences et un tableau sur les filières de terminale du lycée, pour voir ce qui est acquis en droit et ce qui reste à faire.","documents":[{"id":"affiche","type":"fiche","modele":"affiche","entete":"Victime de violences ?","sousTitre":"Campagne de la mairie — affiche imaginée pour l’exercice","emoji":"📞","lignes":[{"texte":"Appelle le 3919 : écoute, gratuit, 24 h/24","id":"z1"},{"texte":"Une ordonnance de protection peut être demandée au juge","id":"z2"},{"texte":"En cas de danger immédiat, appelle la police"}],"pied":"Tu n’es pas seul·e"},{"id":"filieres","type":"tableau","titre":"Part des filles en terminale, lycée de Saint-Aubin","source":"Chiffres imaginés pour l’exercice","colonnes":["Spécialité","Part des filles (%)"],"lignes":[["SES",58],["SVT",62],["Mathématiques",41],["NSI",14]],"enteteLignes":true}],"questions":[{"enonce":"Touche la ligne qui donne le numéro d’écoute gratuit pour les femmes victimes de violences.","aide":"Cherche un numéro à quatre chiffres.","type":"zone","document":"affiche","multiple":false},{"enonce":"Touche la spécialité où la part des filles est la plus faible.","aide":"Compare les pourcentages de la colonne de droite.","type":"zone","document":"filieres","multiple":false},{"enonce":"Classe chaque constat.","aide":"La loi dit-elle déjà l’égalité, ou les faits ne la montrent-ils pas encore ?","type":"categories","categories":[{"id":"c0","texte":"Égalité en droit (acquise)"},{"id":"c1","texte":"Égalité réelle (inachevée)"}],"items":[{"id":"i0","texte":"L’égalité de rémunération à travail de valeur égale, posée en 1972"},{"id":"i1","texte":"Le droit de vote des femmes depuis 1944"},{"id":"i2","texte":"Un écart de revenu salarial d’environ 20 %"},{"id":"i3","texte":"Peu de filles dans les filières scientifiques et techniques"},{"id":"i4","texte":"Très peu de femmes aux postes de direction"}]},{"enonce":"Associe chaque besoin au bon dispositif.","aide":"Distingue l’urgence individuelle de la règle collective.","type":"association","gauche":[{"id":"g0","texte":"Parler à une écoutante, sans payer"},{"id":"g1","texte":"Interdire à un conjoint violent de s’approcher"},{"id":"g2","texte":"Mesurer les écarts entre femmes et hommes en entreprise"},{"id":"g3","texte":"S’engager contre les violences faites aux femmes entre États"}],"droite":[{"id":"d0","texte":"L’index de l’égalité professionnelle"},{"id":"d1","texte":"L’ordonnance de protection"},{"id":"d2","texte":"Le 3919"},{"id":"d3","texte":"La Convention d’Istanbul"}]},{"enonce":"Que montre le tableau sur l’origine d’une partie des écarts de revenu ?","aide":"Les stéréotypes se forment tôt et orientent les choix.","type":"choix","options":[{"id":"a","texte":"Que les lycées imposent leurs spécialités aux filles et aux garçons"},{"id":"b","texte":"Que les filles réussissent moins bien dans toutes les spécialités"},{"id":"c","texte":"Que l’orientation genrée prépare des métiers différents, souvent inégalement payés"},{"id":"d","texte":"Que les garçons choisissent les filières les moins exigeantes du lycée"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"Le **3919** est le numéro d’écoute gratuit, ouvert 24 h/24."},{"cle":{"type":"zone","ids":["r3c1"]},"explication":"En **NSI**, seulement 14 % des élèves sont des filles : le choix des filières reste très genré."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1","i4":"c1"}},"explication":"Le **droit** pose l’égalité depuis longtemps (vote, rémunération). L’**égalité réelle** reste inachevée : écarts de revenu, plafond de verre, orientation."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2","g3":"d3"}},"explication":"3919 pour écouter, **ordonnance de protection** pour protéger, **index** pour mesurer, **Convention d’Istanbul** (2011, ratifiée en 2014) pour agir entre États."},{"cle":{"type":"choix","ids":["c"]},"explication":"La **représentation genrée des formations** oriente les choix bien avant le marché du travail ; elle nourrit la ségrégation professionnelle."}]$ex$::jsonb),
  ('87f5e9ae-40ba-5df4-b79b-6b8045bc37f2'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Quatre annonces passées au crible","competence":"analyser-document","situation":"Le Défenseur des droits reçoit souvent des réclamations sur des annonces. Un stagiaire doit trier quatre annonces pour dire lesquelles posent un problème.","documents":[{"id":"annonces","type":"tableau","titre":"Quatre annonces","source":"Annonces écrites pour l’exercice","colonnes":["N°","Texte de l’annonce"],"lignes":[["1","Garage cherche mécanicien : permis B exigé pour essayer les véhicules des clients."],["2","Boulangerie cherche apprenti : « Nous ne prenons pas de femmes. »"],["3","Cabinet comptable cherche assistant : bonne maîtrise d’un logiciel de comptabilité."],["4","Agence immobilière : logements refusés aux personnes qui habitent le quartier des Tilleuls."]],"enteteLignes":true}],"questions":[{"enonce":"Touche les deux annonces qui constituent une discrimination.","aide":"Cherche celles qui écartent des personnes à cause d’une caractéristique personnelle.","type":"zone","document":"annonces","multiple":true},{"enonce":"Pourquoi l’annonce 1 n’est-elle pas une discrimination ?","aide":"Toute distinction n’est pas une discrimination : sur quoi repose-t-elle ?","type":"choix","options":[{"id":"a","texte":"Parce que le garage est une entreprise trop petite pour être contrôlée"},{"id":"b","texte":"Le permis est une exigence liée au poste et non un critère prohibé par la loi"},{"id":"c","texte":"Parce que toutes les annonces de garage échappent aux règles de la loi"},{"id":"d","texte":"Parce que le permis de conduire est un critère que le droit interdit toujours"}],"multiple":false},{"enonce":"Classe ces critères de sélection.","aide":"Le droit français énumère plus de vingt-cinq critères prohibés.","type":"categories","categories":[{"id":"c0","texte":"Critère prohibé par la loi"},{"id":"c1","texte":"Critère lié au poste, admis"}],"items":[{"id":"i0","texte":"Handicap"},{"id":"i1","texte":"Orientation sexuelle"},{"id":"i2","texte":"Maîtrise d’un logiciel de comptabilité"},{"id":"i3","texte":"Origine"},{"id":"i4","texte":"Diplôme exigé pour le poste"},{"id":"i5","texte":"Lieu de résidence"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1","r3c1"]},"explication":"L’annonce 2 écarte les femmes (**sexe**) et l’annonce 4 écarte des personnes selon leur **lieu de résidence** : deux critères prohibés par la loi."},{"cle":{"type":"choix","ids":["b"]},"explication":"Distinguer devient **discriminer** seulement si la distinction repose sur un critère prohibé. Le permis est lié au poste : l’annonce 1 est licite."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c0","i4":"c1","i5":"c0"}},"explication":"Origine, handicap, orientation sexuelle et lieu de résidence figurent parmi les critères prohibés. Une compétence ou un diplôme **nécessaire au poste** reste admis."}]$ex$::jsonb),
  ('87f5e9ae-40ba-5df4-b79b-6b8045bc37f2'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une règle neutre, un effet qui ne l’est pas","competence":"analyser-document","situation":"Une association qui défend l’égalité d’accès à l’emploi examine des règles d’entreprises, puis réalise un testing avec deux candidatures.","documents":[{"id":"regles","type":"tableau","titre":"Quatre règles d’embauche","source":"Règles écrites pour l’exercice","colonnes":["Règle","Ce qu’elle dit"],"lignes":[["1","Seuls les candidats mesurant plus de 1,80 m sont reçus pour un poste de standardiste."],["2","Les candidats de plus de 50 ans ne sont pas reçus."],["3","Les candidatures de personnes en fauteuil roulant ne sont pas retenues."],["4","Pour un poste de comptable, le candidat doit maîtriser le logiciel utilisé chaque jour."]],"enteteLignes":true},{"id":"testing","type":"tableau","titre":"Testing : deux candidatures envoyées à cinq entreprises","source":"Testing imaginé pour l’exercice","colonnes":["","Candidate A","Candidate B"],"lignes":[["Diplôme","Licence","Licence"],["Expérience","3 ans","3 ans"],["Âge","28 ans","55 ans"],["Réponses favorables","4 sur 5","1 sur 5"]],"enteteLignes":true}],"questions":[{"enonce":"Classe chaque règle.","aide":"Directe : le critère interdit est écrit. Indirecte : la règle semble neutre mais défavorise un groupe sans nécessité.","type":"categories","categories":[{"id":"c0","texte":"Discrimination directe"},{"id":"c1","texte":"Discrimination indirecte"},{"id":"c2","texte":"Pas une discrimination"}],"items":[{"id":"i0","texte":"Règle 1 (taille minimale)"},{"id":"i1","texte":"Règle 2 (plus de 50 ans)"},{"id":"i2","texte":"Règle 4 (logiciel de comptabilité)"},{"id":"i3","texte":"Règle 3 (fauteuil roulant)"}]},{"enonce":"Touche la seule caractéristique des deux CV qui diffère (sans compter les résultats).","aide":"Compare ligne par ligne les deux candidatures.","type":"zone","document":"testing","multiple":false},{"enonce":"Combien de réponses favorables de plus la candidate A a-t-elle obtenues que la candidate B ?","aide":"Soustrais les réponses favorables de B à celles de A.","type":"nombre","unite":"réponses"},{"enonce":"Que permet ce testing, admis comme mode de preuve ?","aide":"Pense à l’aménagement de la charge de la preuve.","type":"choix","options":[{"id":"a","texte":"D’apporter des éléments de fait que l’entreprise devra ensuite justifier"},{"id":"b","texte":"De condamner immédiatement toutes les entreprises testées"},{"id":"c","texte":"D’éviter que la victime ne saisisse un jour le Défenseur des droits"},{"id":"d","texte":"De prouver que l’âge est un critère que la loi autorise"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c2","i3":"c0"}},"explication":"Les règles 2 et 3 utilisent **explicitement** un critère prohibé (âge, handicap). La règle 1 paraît neutre mais défavorise surtout les femmes sans lien avec le poste : **indirecte**. La règle 4 est liée au poste."},{"cle":{"type":"zone","ids":["r2c0"]},"explication":"Les CV sont identiques sauf l’**âge** : c’est le critère que le testing met à l’épreuve."},{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3 réponses","explication":"4 − 1 = **3 réponses** de plus pour la candidate A, alors que tout le reste est identique."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le testing fournit des **éléments de fait** : la victime les présente, et c’est ensuite au défendeur de prouver que sa décision était justifiée."}]$ex$::jsonb),
  ('87f5e9ae-40ba-5df4-b79b-6b8045bc37f2'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le Défenseur des droits est saisi","competence":"argumenter","situation":"M. Perrin, qui se déplace en fauteuil roulant, s’est vu refuser un logement. Un étudiant en droit imagine le parcours qu’il peut suivre.","documents":[{"id":"cas","type":"texte","genre":"article","titre":"Un refus de location","source":"Cas imaginé pour l’exercice","blocs":["M. Perrin visite un appartement à louer à Rivemont. Le gestionnaire lui répond que le propriétaire « ne loue pas aux personnes en situation de handicap ».","La location lui est donc refusée.","M. Perrin note la date, les propos tenus et le nom d’un témoin, puis s’adresse à une autorité indépendante."]},{"id":"loi","type":"texte","genre":"source","titre":"Ce que dit le droit","source":"Résumé adapté pour l’exercice des articles 225-1 et suivants du Code pénal","blocs":["Constitue une discrimination toute distinction entre personnes à raison d’un critère interdit par la loi (origine, sexe, handicap, âge, religion…), lorsqu’elle porte sur une situation visée par la loi : refus d’embauche, de louer, de fournir un bien ou un service. Elle est punie de 3 ans d’emprisonnement et de 45 000 € d’amende au plus."]}],"questions":[{"enonce":"Touche le critère prohibé sur lequel repose le refus.","aide":"Cherche ce qui concerne la personne, pas le logement.","type":"zone","document":"cas","multiple":false},{"enonce":"Touche le mot qui désigne la situation visée par la loi dans laquelle la discrimination a lieu.","aide":"Le droit cite l’embauche, le refus de louer, de fournir un bien ou un service.","type":"zone","document":"cas","multiple":false},{"enonce":"Quelle est l’amende maximale encourue par l’auteur de la discrimination, en euros ?","aide":"Lis la dernière phrase du résumé de la loi.","type":"nombre","unite":"€"},{"enonce":"Quelle autorité M. Perrin peut-il saisir gratuitement ?","aide":"C’est une autorité créée en 2011, saisissable par toute personne.","type":"choix","options":[{"id":"a","texte":"La DILCRAH, qui coordonne la lutte contre la haine anti-LGBT"},{"id":"b","texte":"Le préfet, qui contrôle la légalité des actes des communes"},{"id":"c","texte":"La CNCDH, qui remet un rapport annuel sur le racisme"},{"id":"d","texte":"Le Défenseur des droits, autorité constitutionnelle indépendante"}],"multiple":false},{"enonce":"Remets dans l’ordre la démarche de M. Perrin, de la preuve à la décision.","aide":"La victime avance des faits ; le défendeur se justifie ensuite.","type":"ordre","items":[{"id":"a","texte":"Le propriétaire doit prouver que son refus était justifié"},{"id":"b","texte":"Il présente des éléments laissant supposer une discrimination"},{"id":"c","texte":"Il note les faits : la date, les propos, un témoin"},{"id":"d","texte":"Il saisit gratuitement le Défenseur des droits"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m24"]},"explication":"Le refus repose sur le **handicap**, un critère prohibé."},{"cle":{"type":"zone","ids":["m26"]},"explication":"Il s’agit d’un refus de **location** : une situation visée par la loi."},{"cle":{"type":"nombre","valeur":45000,"tolerance":0},"affichage":"45 000 €","explication":"La peine peut aller jusqu’à 3 ans d’emprisonnement et **45 000 €** d’amende."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le **Défenseur des droits**, créé en 2011, peut être saisi gratuitement par toute personne. La CNCDH publie un rapport, la DILCRAH coordonne l’action publique."},{"cle":{"type":"ordre","ids":["c","d","b","a"]},"explication":"Grâce à l’**aménagement de la charge de la preuve**, la victime présente des éléments de fait ; c’est ensuite au défendeur de démontrer que sa décision reposait sur autre chose."}]$ex$::jsonb),
  ('5b7b35a4-e4f7-56fe-b5f4-f197cfb6d39c'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"L’escalier du lycée de Jade","competence":"analyser-texte","situation":"Jade est élève de première et se déplace en fauteuil roulant. Sa classe étudie la notion de société inclusive à partir de sa situation.","documents":[{"id":"jade","type":"texte","genre":"recit","titre":"Un premier étage inaccessible","source":"Texte écrit pour l’exercice","blocs":["Jade se déplace en fauteuil roulant. Au lycée, la salle de SVT se trouve au premier étage et l’on n’y accède que par un escalier.","Jade attend en bas pendant que ses camarades montent. Elle pense : « Ce n’est pas mon fauteuil qui me gêne, c’est le bâtiment. »"]}],"questions":[{"enonce":"Touche le mot qui désigne l’obstacle qui crée la situation de handicap.","aide":"Cherche l’élément du bâtiment qui empêche Jade de monter.","type":"zone","document":"jade","multiple":false},{"enonce":"Dans l’approche sociale, où se situe le handicap ?","aide":"Jade dit : « Ce n’est pas mon fauteuil qui me gêne… »","type":"choix","options":[{"id":"a","texte":"Dans le regard des élèves qui n’aident pas leur camarade à monter"},{"id":"b","texte":"Dans une déficience individuelle que la personne doit compenser seule"},{"id":"c","texte":"Dans la rencontre entre une déficience et un environnement inadapté"},{"id":"d","texte":"Dans le fauteuil roulant, qui limite les mouvements de la personne"}],"multiple":false},{"enonce":"Associe chaque sigle à ce qu’il désigne dans la scolarité de Jade.","aide":"Un sigle désigne un lieu, une personne, un projet.","type":"association","gauche":[{"id":"g0","texte":"MDPH"},{"id":"g1","texte":"AESH"},{"id":"g2","texte":"PPS"},{"id":"g3","texte":"Ulis"}],"droite":[{"id":"d0","texte":"Une unité localisée pour l’inclusion scolaire"},{"id":"d1","texte":"L’accompagnant qui aide l’élève en classe"},{"id":"d2","texte":"La maison départementale qui sert de guichet unique"},{"id":"d3","texte":"Le projet personnalisé de scolarisation"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m26"]},"explication":"C’est l’**escalier** : l’environnement inadapté, qui transforme une déficience en situation de handicap."},{"cle":{"type":"choix","ids":["c"]},"explication":"L’approche **sociale** voit le handicap dans la **rencontre** entre une déficience et un environnement inadapté. Il faut donc adapter l’environnement."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g0":"d2","g2":"d3"}},"explication":"La **MDPH** est le guichet unique, l’**AESH** accompagne, le **PPS** organise la scolarité, l’**Ulis** est une unité d’inclusion."}]$ex$::jsonb),
