   $ex${"titre":"Le quota de 6 % dans quatre entreprises","competence":"lire-tableau","situation":"Une inspectrice contrôle l’emploi des travailleurs handicapés dans quatre entreprises d’une même ville. Elle rencontre aussi Hugo, comptable malvoyant.","documents":[{"id":"entreprises","type":"tableau","titre":"Les quatre entreprises","source":"Entreprises et effectifs imaginés pour l’exercice","colonnes":["Entreprise","Salariés","Salariés handicapés"],"lignes":[["Atelier Lumière",15,0],["Brasserie du Port",200,9],["Cabinet Rivière",50,3],["Dépôt Martin",100,4]],"enteteLignes":true},{"id":"hugo","type":"texte","genre":"recit","titre":"Le poste de Hugo","source":"Texte écrit pour l’exercice","blocs":["Hugo est comptable et malvoyant. Son employeur lui a installé un logiciel qui lit l’écran à voix haute et un grand écran, pour qu’il puisse travailler comme ses collègues."]}],"questions":[{"enonce":"Touche l’entreprise qui n’est pas concernée par l’obligation d’emploi de 6 %.","aide":"L’obligation s’applique à partir de 20 salariés.","type":"zone","document":"entreprises","multiple":false},{"enonce":"Combien de travailleurs handicapés manque-t-il à la Brasserie du Port pour atteindre 6 % de ses effectifs ?","aide":"Calcule 6 % de 200, puis retire les 9 déjà employés.","type":"nombre","unite":"salariés"},{"enonce":"Quelle part de ses effectifs le Dépôt Martin consacre-t-il à l’emploi de travailleurs handicapés ?","aide":"Divise 4 par 100, puis exprime le résultat en pourcentage.","type":"nombre","unite":"%"},{"enonce":"Comment s’appelle l’obligation que remplit l’employeur de Hugo ?","aide":"L’employeur adapte le poste pour permettre le travail.","type":"choix","options":[{"id":"a","texte":"Le versement d’une contribution à défaut de respecter le quota"},{"id":"b","texte":"L’aménagement raisonnable du poste de travail de l’employé"},{"id":"c","texte":"Le projet personnalisé de scolarisation de l’élève concerné"},{"id":"d","texte":"La prestation de compensation du handicap versée à la personne"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c0"]},"explication":"L’Atelier Lumière a **15 salariés** : sous le seuil de 20, il n’est pas soumis à l’obligation."},{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3 salariés","explication":"6 % de 200 = 12 ; 12 − 9 = **3** travailleurs handicapés manquants."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4 %","explication":"4 ÷ 100 = **4 %**, soit moins que les 6 % exigés : l’entreprise doit verser une contribution à défaut."},{"cle":{"type":"choix","ids":["b"]},"explication":"L’employeur doit procéder à des **aménagements raisonnables** : adapter le poste pour que la personne puisse travailler."}]$ex$::jsonb),
  ('5b7b35a4-e4f7-56fe-b5f4-f197cfb6d39c'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"La commune qui lève les obstacles","competence":"analyser-document","situation":"À Valbonne-sur-Tarn, commune imaginaire, un article de presse raconte l’histoire de Samir, 16 ans, malvoyant. Les élèves le comparent aux grandes dates de la loi.","documents":[{"id":"presse","type":"texte","genre":"article","titre":"À Valbonne, un lycéen change la mairie","source":"Article écrit pour l’exercice : personnes et lieux imaginés","blocs":["Samir est malvoyant. Les panneaux du lycée sont écrits en trop petits caractères et le formulaire de demande d’aide n’existe qu’en version papier minuscule.","Le maire a déclaré : « Ce n’est pas à Samir de s’habituer à nos bâtiments. C’est à la commune de lever les obstacles. »","La mairie va agrandir les caractères, installer des bandes guidantes et proposer un dossier unique, à déposer en un seul endroit."]},{"id":"frise","type":"frise","titre":"Quelques dates","source":"Dates du cours","debut":1985,"fin":2015,"pas":5,"evenements":[{"id":"z1","date":1987,"nom":"Quota de 6 %"},{"id":"z2","date":2005,"nom":"Loi du 11 février"},{"id":"z3","date":2006,"nom":"Convention ONU"},{"id":"z4","date":2010,"nom":"Ratification France"}]}],"questions":[{"enonce":"Touche la date de la loi qui pose les trois piliers : accessibilité généralisée, compensation, guichet unique.","aide":"C’est la loi « pour l’égalité des droits et des chances, la participation et la citoyenneté des personnes handicapées ».","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent l’adoption de la Convention de l’ONU de sa ratification par la France ?","aide":"Soustrais 2006 à 2010.","type":"nombre","unite":"ans"},{"enonce":"Range chaque mesure sous le pilier de la loi de 2005 auquel elle se rattache.","aide":"Trois piliers : lever les obstacles, aider financièrement, simplifier les démarches.","type":"categories","categories":[{"id":"c0","texte":"Accessibilité généralisée"},{"id":"c1","texte":"Compensation"},{"id":"c2","texte":"Guichet unique"}],"items":[{"id":"i0","texte":"Une MDPH dans chaque département"},{"id":"i1","texte":"Des transports adaptés"},{"id":"i2","texte":"Une rampe d’accès à la mairie"},{"id":"i3","texte":"Un dossier unique déposé en un seul endroit"},{"id":"i4","texte":"L’allocation aux adultes handicapés (AAH)"},{"id":"i5","texte":"La prestation de compensation du handicap"}]},{"enonce":"En quoi la phrase du maire illustre-t-elle l’approche sociale du handicap ?","aide":"Regarde qui doit changer dans la phrase du maire.","type":"choix","options":[{"id":"a","texte":"Elle affirme que le handicap n’existe pas lorsqu’on y pense moins"},{"id":"b","texte":"Elle confie à l’État la totalité des dépenses liées à tous les handicaps"},{"id":"c","texte":"Elle demande à la personne de compenser seule sa déficience individuelle"},{"id":"d","texte":"Elle demande à l’environnement de s’adapter, et non à la personne seule"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"La **loi du 11 février 2005** pose les trois piliers."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4 ans","explication":"2010 − 2006 = **4 ans**."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c0","i2":"c0","i3":"c2","i4":"c1","i5":"c1"}},"explication":"L’**accessibilité** lève les obstacles ; la **compensation** aide financièrement ; le **guichet unique** (la MDPH) simplifie les démarches."},{"cle":{"type":"choix","ids":["d"]},"explication":"L’approche **sociale** place le handicap dans la rencontre entre une déficience et un environnement inadapté : c’est donc **l’environnement** qu’il faut adapter."}]$ex$::jsonb),
  ('4adecebe-8eff-5410-b73d-3ae75a40033c'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La frise des lois contre la haine","competence":"se-reperer-temps","situation":"Pour un exposé, une élève range sur une frise les lois qui encadrent la liberté d’expression et punissent les propos haineux.","documents":[{"id":"frise","type":"frise","titre":"Quatre lois repères","source":"Dates du cours","debut":1880,"fin":2020,"pas":20,"evenements":[{"id":"z1","date":1881,"nom":"Loi sur la presse"},{"id":"z2","date":1972,"nom":"Loi Pleven"},{"id":"z3","date":1990,"nom":"Loi Gayssot"},{"id":"z4","date":2004,"nom":"Loi du 30 décembre"}]}],"questions":[{"enonce":"Touche la loi qui punit la contestation de crimes contre l’humanité.","aide":"C’est une loi de juillet 1990.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent la loi Pleven de la loi du 30 décembre 2004 ?","aide":"Soustrais 1972 à 2004.","type":"nombre","unite":"ans"},{"enonce":"Associe chaque loi à ce qu’elle apporte.","aide":"Chaque loi ajoute un cas à la précédente.","type":"association","gauche":[{"id":"g0","texte":"Loi du 29 juillet 1881"},{"id":"g1","texte":"Loi Pleven"},{"id":"g2","texte":"Loi Gayssot"},{"id":"g3","texte":"Loi du 30 décembre 2004"}],"droite":[{"id":"d0","texte":"Étend la répression aux injures sexistes, homophobes et handiphobes"},{"id":"d1","texte":"Punit la provocation à la haine, la diffamation et l’injure racistes"},{"id":"d2","texte":"Le cadre général des abus de la liberté d’expression"},{"id":"d3","texte":"Punit la contestation de crimes contre l’humanité"}]}]}$ex$::jsonb,
