  ('4adecebe-8eff-5410-b73d-3ae75a40033c'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Critiquer une idée ou viser des personnes","competence":"argumenter","situation":"Une modératrice de réseau social doit trier cinq propos. Elle se demande lesquels la loi autorise, et pour les autres, quelle loi s’applique.","documents":[{"id":"propos","type":"tableau","titre":"Cinq propos","source":"Propos écrits pour l’exercice","colonnes":["N°","Propos"],"lignes":[["1","« Cette doctrine religieuse est absurde, et voici mes arguments, un par un. »"],["2","« Les gens du voyage sont tous des voleurs : il faut les chasser. »"],["3","Un message en ligne affirme que le génocide des Juifs n’a jamais eu lieu."],["4","« Je trouve ce programme politique mauvais pour le pays. »"],["5","Un tag « sale homo » est écrit sur la porte d’un voisin."]],"enteteLignes":true}],"questions":[{"enonce":"Touche les deux propos que la loi autorise.","aide":"La loi permet de critiquer une idée, pas d’attaquer des personnes pour ce qu’elles sont.","type":"zone","document":"propos","multiple":true},{"enonce":"Associe chaque propos puni à la loi qui le réprime.","aide":"Pleven : racisme ; Gayssot : contestation de crimes contre l’humanité ; 2004 : sexisme, homophobie, handicap.","type":"categories","categories":[{"id":"c0","texte":"Loi Pleven (1972)"},{"id":"c1","texte":"Loi Gayssot (1990)"},{"id":"c2","texte":"Loi du 30 décembre 2004"}],"items":[{"id":"i0","texte":"Propos n° 5 (le tag homophobe)"},{"id":"i1","texte":"Propos n° 3 (le génocide des Juifs)"},{"id":"i2","texte":"Propos n° 2 (les gens du voyage)"}]},{"enonce":"Pourquoi le propos n° 1 est-il permis alors que le propos n° 2 est puni ?","aide":"Qu’est-ce qui est visé : une idée, ou des personnes ?","type":"choix","options":[{"id":"a","texte":"Le second a été écrit en ligne alors que le premier est resté privé"},{"id":"b","texte":"Le premier est plus long que le second et donc mieux argumenté"},{"id":"c","texte":"Le premier critique une doctrine, le second attaque un groupe de personnes"},{"id":"d","texte":"Le premier est écrit par un adulte et le second par un élève de lycée"}],"multiple":false},{"enonce":"Remets dans l’ordre la démarche face à un contenu manifestement illicite repéré en ligne.","aide":"On repère, on signale, la plateforme agit.","type":"ordre","items":[{"id":"a","texte":"La plateforme prévenue doit le retirer promptement"},{"id":"b","texte":"Tu le signales à la plateforme ou sur PHAROS"},{"id":"c","texte":"Tu repères un contenu manifestement illicite"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1","r3c1"]},"explication":"Les propos **1** et **4** critiquent une doctrine ou un programme : c’est permis. Les autres attaquent des personnes ou nient un crime contre l’humanité."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c1","i2":"c0"}},"explication":"Le propos 2 est une injure à caractère raciste (**Pleven**), le 3 une **contestation de crime contre l’humanité** (Gayssot), le 5 une injure homophobe (**loi de 2004**)."},{"cle":{"type":"choix","ids":["c"]},"explication":"On peut **critiquer une idée, une doctrine, une religion** ; on ne peut pas **attaquer une personne ou un groupe** pour ce qu’il est."},{"cle":{"type":"ordre","ids":["c","b","a"]},"explication":"PHAROS recueille les signalements ; les plateformes doivent **retirer promptement** les contenus manifestement illicites qui leur sont notifiés."}]$ex$::jsonb),
  ('4adecebe-8eff-5410-b73d-3ae75a40033c'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un message sur le forum du lycée","competence":"analyser-document","situation":"Sur le forum du lycée, un message déclenche une conversation entre Alex et Cléo. Ils cherchent où passe la limite de la liberté d’expression.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Alex et Cléo","participants":[{"nom":"Cléo","emoji":"👧","cote":"gauche"},{"nom":"Alex","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Cléo","texte":"Tu as vu le message de Bao sur le forum ? « Les gens de cette religion sont des parasites. »"},{"qui":"Alex","texte":"Oui. Dire qu’une doctrine me paraît absurde, je peux. Mais traiter des personnes comme ça, non."},{"qui":"Cléo","texte":"Je l’ai signalé à la plateforme."}]},{"id":"panneau","type":"fiche","modele":"panneau","entete":"Contenu illicite en ligne ?","sousTitre":"Panneau imaginé pour l’exercice","emoji":"🚩","lignes":[{"texte":"Signale-le à la plateforme où tu l’as vu","id":"z1"},{"texte":"Ou sur la plateforme officielle PHAROS","id":"z2"}],"pied":"Ne le partage pas"}],"questions":[{"enonce":"Touche le mot du message de Bao qui vise des personnes plutôt qu’une idée.","aide":"Cherche le mot injurieux appliqué aux gens.","type":"zone","document":"sms","multiple":false},{"enonce":"Quelle phrase résume la limite que dessinent Alex et Cléo ?","aide":"Relis la réplique d’Alex.","type":"choix","options":[{"id":"a","texte":"La loi permet de critiquer une idée mais punit l’attaque contre un groupe"},{"id":"b","texte":"La loi punit toute critique d’une religion, quelle qu’elle soit"},{"id":"c","texte":"La loi autorise tout propos tant qu’il est écrit sur un forum privé"},{"id":"d","texte":"La loi punit toutes les opinions, même quand on les garde pour soi"}],"multiple":false},{"enonce":"Touche la ligne qui désigne la plateforme officielle de signalement.","aide":"Cherche un nom en majuscules.","type":"zone","document":"panneau","multiple":false},{"enonce":"Associe chaque acteur à son rôle.","aide":"Distingue celui qui signale, celui qui retire, celui qui poursuit, celui qui définit.","type":"association","gauche":[{"id":"g0","texte":"PHAROS"},{"id":"g1","texte":"Une plateforme en ligne"},{"id":"g2","texte":"Une association habilitée"},{"id":"g3","texte":"La loi du 29 juillet 1881"}],"droite":[{"id":"d0","texte":"Retire promptement les contenus manifestement illicites signalés"},{"id":"d1","texte":"Recueille les signalements de contenus illicites"},{"id":"d2","texte":"Peut se porter partie civile"},{"id":"d3","texte":"Définit les abus de la liberté d’expression"}]},{"enonce":"Complète la règle à retenir.","aide":"Provoquer, injurier, diffamer sont des actes.","type":"trous","segments":["La loi ne punit pas le fait de ",0,", mais des actes de ",1," publics."],"banque":["religion","croire","langage","penser"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m17"]},"explication":"**« Parasites »** désigne des personnes en raison de leur religion : c’est une attaque contre un groupe, non une critique d’une doctrine."},{"cle":{"type":"choix","ids":["a"]},"explication":"Critiquer une doctrine est permis ; **attaquer des personnes** pour ce qu’elles sont est puni. La loi ne punit pas le fait de penser, mais des actes de langage publics."},{"cle":{"type":"zone","ids":["z2"]},"explication":"**PHAROS** recueille les signalements de contenus illicites en ligne."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2","g3":"d3"}},"explication":"**PHAROS** reçoit les signalements ; les **plateformes** retirent ; les **associations** (loi Pleven) se portent partie civile ; la **loi de 1881** définit les abus."},{"cle":{"type":"trous","trous":[["penser"],["langage"]]},"affichage":"penser · langage","explication":"La loi ne punit pas le fait de **penser**, mais des actes de **langage** publics : provoquer, injurier, diffamer, nier un crime contre l’humanité."}]$ex$::jsonb),
  ('367f457f-4a36-501c-9939-6cda87bc1606'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Deux articles pour une République laïque","competence":"analyser-texte","situation":"Pour son exposé, Inès lit les deux premiers articles de la loi de 1905 et cherche ce que chacun garantit.","documents":[{"id":"loi","type":"texte","genre":"source","titre":"La loi du 9 décembre 1905","source":"Articles 1 et 2, texte adapté pour l’exercice","blocs":["Article 1er. La République assure la liberté de conscience. Elle garantit le libre exercice des cultes, sous les restrictions utiles à l’ordre public.","Article 2. La République ne reconnaît, ne salarie ni ne subventionne aucun culte."]}],"questions":[{"enonce":"Touche les trois verbes par lesquels l’article 2 fixe la neutralité de l’État.","aide":"Cherche les trois verbes qui suivent « La République ne ».","type":"zone","document":"loi","multiple":true},{"enonce":"Que garantit l’article 1er ?","aide":"Cet article pose une liberté, l’article 2 une neutralité.","type":"choix","options":[{"id":"a","texte":"La neutralité de l’État et de tous ses agents"},{"id":"b","texte":"L’interdiction de tout signe religieux dans l’espace public"},{"id":"c","texte":"La liberté de conscience et le libre exercice des cultes"},{"id":"d","texte":"Le financement public de chacun des cultes"}],"multiple":false},{"enonce":"Associe chaque exigence de la laïcité à son contenu.","aide":"Trois exigences indissociables.","type":"association","gauche":[{"id":"g0","texte":"Liberté de conscience"},{"id":"g1","texte":"Neutralité"},{"id":"g2","texte":"Égalité"}],"droite":[{"id":"d0","texte":"Aucune conviction n’ouvre de privilège ni ne justifie de discrimination"},{"id":"d1","texte":"Croire, ne pas croire ou changer de conviction"},{"id":"d2","texte":"Un service public ne prend pas parti"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m29","m31","m34"]},"explication":"L’État ne **reconnaît**, ne **salarie** ni ne **subventionne** aucun culte : c’est sa neutralité."},{"cle":{"type":"choix","ids":["c"]},"explication":"L’article 1er garantit une **liberté** : la liberté de conscience et le libre exercice des cultes."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"**Liberté de conscience**, **neutralité** et **égalité** forment les trois exigences de la laïcité."}]$ex$::jsonb),
  ('367f457f-4a36-501c-9939-6cda87bc1606'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"À qui s’impose la neutralité ?","competence":"argumenter","situation":"Au conseil municipal, des élus s’interrogent sur ce que la laïcité interdit et sur ce qu’elle permet. Ils étudient quatre cas, puis un projet d’arrêté.","documents":[{"id":"cas","type":"tableau","titre":"Quatre cas","source":"Cas écrits pour l’exercice","colonnes":["Cas","Situation"],"lignes":[["1","Une élève de collège public porte un signe qui manifeste ostensiblement son appartenance religieuse."],["2","Un agent de la préfecture reçoit le public en portant un signe religieux visible."],["3","Une passante porte un signe religieux dans la rue."],["4","Un voyageur lit un livre religieux dans le tramway."]],"enteteLignes":true},{"id":"conseil","type":"texte","genre":"source","titre":"Compte rendu du conseil municipal","source":"Texte écrit pour l’exercice","blocs":["Le maire propose un arrêté qui fixe les horaires des sonneries de cloches et encadre la procession prévue sur la voie publique.","Une conseillère demande sur quels articles de la loi de 1905 il s’appuie."]}],"questions":[{"enonce":"Touche les deux cas où la règle française interdit le signe religieux.","aide":"La loi vise les élèves des écoles publiques et les agents publics.","type":"zone","document":"cas","multiple":true},{"enonce":"Associe chaque règle à ceux qu’elle concerne ou à ce qu’elle fait.","aide":"Distingue élèves, agents, texte de synthèse, police des cultes.","type":"association","gauche":[{"id":"g0","texte":"Loi du 15 mars 2004"},{"id":"g1","texte":"Stricte neutralité"},{"id":"g2","texte":"Charte de la laïcité à l’école (2013)"},{"id":"g3","texte":"Articles 27 et 28 de la loi de 1905"}],"droite":[{"id":"d0","texte":"Encadrent la police des cultes"},{"id":"d1","texte":"Rassemble les règles de laïcité à l’école"},{"id":"d2","texte":"Les agents publics"},{"id":"d3","texte":"Les élèves des écoles, collèges et lycées publics"}]},{"enonce":"Touche les deux éléments que le maire veut encadrer : ce sont des manifestations extérieures du culte.","aide":"Cherche un son et un défilé sur la voie publique.","type":"zone","document":"conseil","multiple":true},{"enonce":"Sur quels articles de la loi de 1905 le maire peut-il s’appuyer pour cet arrêté ?","aide":"Sonneries et manifestations extérieures relèvent de la « police des cultes ».","type":"choix","options":[{"id":"a","texte":"La loi du 15 mars 2004, qui vise les signes à l’école"},{"id":"b","texte":"La Charte de la laïcité à l’école publiée en 2013"},{"id":"c","texte":"Les articles 27 et 28, qui encadrent la police des cultes"},{"id":"d","texte":"Les articles 1er et 2, qui posent la liberté et la neutralité"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1","r1c1"]},"explication":"Cas 1 : la **loi du 15 mars 2004** interdit les signes ostensibles aux élèves. Cas 2 : la **stricte neutralité** s’impose aux agents publics. Les cas 3 et 4 sont permis : la neutralité s’impose à l’État, pas aux citoyens."},{"cle":{"type":"association","paires":{"g3":"d0","g2":"d1","g1":"d2","g0":"d3"}},"explication":"La loi de **2004** concerne les élèves ; la **neutralité** les agents ; la **Charte** (2013) rassemble les règles ; les **articles 27 et 28** encadrent la police des cultes."},{"cle":{"type":"zone","ids":["m10","m16"]},"explication":"Les **sonneries** et la **procession** sont des manifestations extérieures : leur cadre relève de la police des cultes."},{"cle":{"type":"choix","ids":["c"]},"explication":"Les **articles 27 et 28** encadrent la police des cultes : sonneries, manifestations extérieures, emblèmes dans les lieux publics."}]$ex$::jsonb),
  ('367f457f-4a36-501c-9939-6cda87bc1606'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Quand la Cour européenne juge une restriction","competence":"analyser-document","situation":"Une cour imaginaire examine trois restrictions à la liberté de manifester sa religion, avec les critères de la Cour européenne des droits de l’homme. Les élèves regardent aussi ce que dit la Charte de la laïcité à l’école.","documents":[{"id":"charte","type":"fiche","modele":"affiche","entete":"Charte de la laïcité à l’école","sousTitre":"Extraits adaptés pour l’exercice (2013)","emoji":"🏫","lignes":[{"texte":"La laïcité garantit à chacun la liberté de conscience","id":"z1"},{"texte":"Elle garantit l’égalité : aucune conviction n’ouvre de privilège","id":"z2"},{"texte":"Les agents publics sont tenus à la stricte neutralité","id":"z3"},{"texte":"Les élèves ne portent pas de signe manifestant ostensiblement une appartenance religieuse","id":"z4"}]},{"id":"restrictions","type":"tableau","titre":"Trois restrictions examinées","source":"Cas imaginés pour l’exercice","colonnes":["Cas","Restriction"],"lignes":[["A","Une loi précise interdit à l’agent d’un guichet public de porter un signe religieux, pour garantir la neutralité du service, pendant son service seulement."],["B","Un directeur interdit tout signe religieux dans son service par une simple note orale, alors qu’aucun texte ne le prévoit."],["C","Une loi interdit toute manifestation d’une croyance, même à l’intérieur de son propre logement."]],"enteteLignes":true}],"questions":[{"enonce":"Touche la ligne de la Charte qui s’applique aux agents publics.","aide":"Cherche la ligne qui parle de « neutralité ».","type":"zone","document":"charte","multiple":false},{"enonce":"Selon les critères de la Cour (prévue par la loi, but légitime, proportionnée), classe chaque cas.","aide":"La Cour vérifie trois conditions à la fois.","type":"categories","categories":[{"id":"c0","texte":"Restriction admissible"},{"id":"c1","texte":"Restriction non admissible"}],"items":[{"id":"i0","texte":"Cas B"},{"id":"i1","texte":"Cas C"},{"id":"i2","texte":"Cas A"}]},{"enonce":"Pourquoi la restriction du cas B ne passe-t-elle pas le contrôle de la Cour ?","aide":"Relis le cas B : sur quoi repose l’interdiction ?","type":"choix","options":[{"id":"a","texte":"Parce que seuls les élèves peuvent être soumis à une restriction"},{"id":"b","texte":"Parce qu’elle poursuit un but que la Cour juge toujours illégitime"},{"id":"c","texte":"Parce qu’elle est jugée trop sévère pour la vie privée de la personne"},{"id":"d","texte":"Parce qu’aucune loi ne la prévoit : ce n’est qu’une consigne orale"}],"multiple":false},{"enonce":"Associe chaque condition à la question que la Cour se pose.","aide":"Trois conditions : le texte, le but, la mesure.","type":"association","gauche":[{"id":"g0","texte":"Prévue par la loi"},{"id":"g1","texte":"But légitime"},{"id":"g2","texte":"Proportionnée"}],"droite":[{"id":"d0","texte":"Reste-t-elle limitée à ce qui est nécessaire ?"},{"id":"d1","texte":"Un texte précis l’autorise-t-il ?"},{"id":"d2","texte":"Protège-t-elle l’ordre public ou les droits d’autrui ?"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"La **stricte neutralité** s’impose aux agents publics, non aux usagers."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0"}},"explication":"Le cas **A** remplit les trois conditions. Le **B** n’est pas prévu par la loi. Le **C** est disproportionné : il vise même la sphère privée."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le cas B échoue à la première condition : la restriction doit être **prévue par la loi**, pas par une note orale."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"La Cour admet une restriction si elle est **prévue par la loi**, poursuit un **but légitime** et reste **proportionnée**. La laïcité française n’est donc pas le seul modèle possible en Europe."}]$ex$::jsonb),
  ('27f47db5-6f14-5c5e-b867-1d2dd49f4583'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Qui s’occupe de quoi dans la République ?","competence":"observer-schema","situation":"Camille, élève de première, veut comprendre pourquoi son école primaire, son ancien collège et son lycée dépendent de niveaux différents. Elle dessine un schéma des niveaux de la République.","documents":[{"id":"niveaux","type":"schema","titre":"Les niveaux de la République","source":"Schéma simplifié pour l’exercice","largeur":340,"hauteur":230,"elements":[{"forme":"rect","x":20,"y":14,"l":300,"h":52,"arrondi":10,"texte":"L’État","teinte":"violet","motif":"clair","id":"z1","zone":true},{"forme":"texte","x":170,"y":96,"texte":"Trois niveaux de collectivités, chacun avec un conseil élu","taille":"petit","italique":true,"ancre":"milieu"},{"forme":"rect","x":20,"y":112,"l":96,"h":60,"arrondi":10,"texte":"Commune","teinte":"violet","motif":"clair","id":"z2","zone":true},{"forme":"rect","x":122,"y":112,"l":96,"h":60,"arrondi":10,"texte":"Département","teinte":"violet","motif":"clair","id":"z3","zone":true},{"forme":"rect","x":224,"y":112,"l":96,"h":60,"arrondi":10,"texte":"Région","teinte":"violet","motif":"clair","id":"z4","zone":true},{"forme":"texte","x":68,"y":192,"texte":"conseil","taille":"petit","ancre":"milieu"},{"forme":"texte","x":68,"y":206,"texte":"municipal","taille":"petit","ancre":"milieu"},{"forme":"texte","x":170,"y":192,"texte":"conseil","taille":"petit","ancre":"milieu"},{"forme":"texte","x":170,"y":206,"texte":"départemental","taille":"petit","ancre":"milieu"},{"forme":"texte","x":272,"y":192,"texte":"conseil","taille":"petit","ancre":"milieu"},{"forme":"texte","x":272,"y":206,"texte":"régional","taille":"petit","ancre":"milieu"}]}],"questions":[{"enonce":"Touche le niveau qui a la charge des lycées.","aide":"Collèges, lycées : le département et la région se partagent ces deux écoles.","type":"zone","document":"niveaux","multiple":false},{"enonce":"Associe chaque compétence au niveau qui l’exerce.","aide":"Du plus proche au plus lointain : commune, département, région, État.","type":"association","gauche":[{"id":"g0","texte":"Les écoles primaires"},{"id":"g1","texte":"Les routes départementales"},{"id":"g2","texte":"La formation professionnelle"},{"id":"g3","texte":"La justice"}],"droite":[{"id":"d0","texte":"La région"},{"id":"d1","texte":"L’État"},{"id":"d2","texte":"La commune"},{"id":"d3","texte":"Le département"}]},{"enonce":"Touche le niveau qui garde les fonctions régaliennes : défense, justice, monnaie, police, diplomatie.","aide":"Ce niveau n’est pas une collectivité décentralisée.","type":"zone","document":"niveaux","multiple":false},{"enonce":"Complète la formule à retenir.","aide":"Un seul pouvoir législatif, mais des collectivités qui s’administrent.","type":"trous","segments":["La France est un État ",0," décentralisé, et non un État ",1,"."],"banque":["unitaire","régional","centralisé","fédéral"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z4"]},"explication":"La **région** s’occupe des lycées, de la formation professionnelle et des transports régionaux. Le département a la charge des collèges."},{"cle":{"type":"association","paires":{"g2":"d0","g3":"d1","g0":"d2","g1":"d3"}},"explication":"La **commune** gère l’école primaire, le **département** ses routes, la **région** la formation professionnelle ; la **justice** reste à l’**État**."},{"cle":{"type":"zone","ids":["z1"]},"explication":"Défense, justice, monnaie, police et diplomatie restent à l’**État**. Les collectivités administrent, elles ne légifèrent pas."},{"cle":{"type":"trous","trous":[["unitaire"],["federal"]]},"affichage":"unitaire · fédéral","explication":"La France est un État **unitaire** décentralisé, pas un État **fédéral** : les collectivités n’ont pas de pouvoir législatif propre."}]$ex$::jsonb),
  ('27f47db5-6f14-5c5e-b867-1d2dd49f4583'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Décentraliser, déconcentrer : qui décide ?","competence":"analyser-texte","situation":"À la mairie de Fontvallon, commune imaginaire, quatre décisions sont à l’ordre du jour. Une élève de première doit dire, pour chacune, qui l’exerce.","documents":[{"id":"decisions","type":"tableau","titre":"Quatre décisions","source":"Décisions imaginées pour l’exercice","colonnes":["N°","Décision"],"lignes":[["1","Le conseil régional vote le budget des transports régionaux."],["2","Le préfet vérifie qu’une délibération du conseil municipal respecte la loi."],["3","Le conseil municipal, élu, fixe des règles d’urbanisme."],["4","Le Parlement vote une loi qui s’applique sur tout le territoire."]],"enteteLignes":true},{"id":"constit","type":"texte","genre":"source","titre":"La Constitution","source":"Articles 1er et 72, résumés pour l’exercice","blocs":["Article 1er. L’organisation de la République est décentralisée.","Article 72. Les collectivités territoriales s’administrent librement par des conseils élus."]}],"questions":[{"enonce":"Classe chaque décision.","aide":"Décentralisation : des élus locaux. Déconcentration : les agents de l’État sur place.","type":"categories","categories":[{"id":"c0","texte":"Décentralisation"},{"id":"c1","texte":"Déconcentration"},{"id":"c2","texte":"Compétence de l’État"}],"items":[{"id":"i0","texte":"Décision 2"},{"id":"i1","texte":"Décision 1"},{"id":"i2","texte":"Décision 4"},{"id":"i3","texte":"Décision 3"}]},{"enonce":"Touche le mot qui dit comment les conseils des collectivités sont désignés.","aide":"Cherche le mot qui s’oppose à « nommés ».","type":"zone","document":"constit","multiple":false},{"enonce":"Complète la définition.","aide":"La première des deux notions apparaît dans l’article 1er.","type":"trous","segments":["La ",0," transfère des compétences à des élus locaux ; la ",1," les confie à des agents de l’État."],"banque":["subsidiarité","décentralisation","déconcentration","fédéralisme"]},{"enonce":"Pourquoi la France n’est-elle pas un État fédéral ?","aide":"Dans un État fédéral, les entités fédérées votent leurs propres lois.","type":"choix","options":[{"id":"a","texte":"Parce que ses collectivités n’ont pas de pouvoir législatif propre"},{"id":"b","texte":"Parce que ses collectivités sont toutes dirigées par un préfet"},{"id":"c","texte":"Parce que ses collectivités n’ont aucun budget ni aucun conseil élu"},{"id":"d","texte":"Parce que l’État n’y exerce aucune compétence sur son territoire"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c2","i3":"c0"}},"explication":"Les décisions 1 et 3 sont prises par des **élus locaux** (décentralisation). Le préfet (décision 2) représente l’**État** : c’est de la **déconcentration**. La loi (décision 4) relève de l’**État**."},{"cle":{"type":"zone","ids":["m20"]},"explication":"Les conseils sont **élus** : c’est ce qui distingue la décentralisation de la déconcentration."},{"cle":{"type":"trous","trous":[["decentralisation"],["deconcentration"]]},"affichage":"décentralisation · déconcentration","explication":"La **décentralisation** transfère à des collectivités élues ; la **déconcentration** confie des tâches aux représentants de l’État, comme le préfet."},{"cle":{"type":"choix","ids":["a"]},"explication":"Les collectivités françaises administrent mais **ne légifèrent pas** : la loi est la même pour tous."}]$ex$::jsonb),
  ('27f47db5-6f14-5c5e-b867-1d2dd49f4583'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le « peuple corse » censuré en 1991","competence":"analyser-document","situation":"En 1991, une loi sur la Corse a soulevé une question de principe. Des lycéens la reprennent pour comprendre le sens du mot « indivisible », puis comparent trois États imaginaires.","documents":[{"id":"loi1991","type":"texte","genre":"source","titre":"Une mention censurée","source":"Résumé écrit pour l’exercice","blocs":["En 1991, un projet de loi sur l’organisation de la Corse mentionnait « le peuple corse, composante du peuple français ».","Le Conseil constitutionnel a censuré cette mention : la République est indivisible, et il n’existe qu’un seul peuple français."]},{"id":"etats","type":"tableau","titre":"Trois États imaginaires","source":"États imaginés pour l’exercice","colonnes":["État","Organisation"],"lignes":[["X","Chaque entité vote ses propres lois et a son propre Parlement."],["Y","Des collectivités élues gèrent des compétences, mais une seule loi, votée au niveau national, s’applique partout."],["Z","Les collectivités n’ont ni budget ni élus : le représentant de l’État décide de tout sur place."]],"enteteLignes":true}],"questions":[{"enonce":"Touche l’adjectif qui qualifie le peuple dans la mention censurée.","aide":"Cherche l’adjectif entre guillemets, avant « composante du peuple français ».","type":"zone","document":"loi1991","multiple":false},{"enonce":"Pourquoi le Conseil constitutionnel a-t-il censuré cette mention ?","aide":"Relis la dernière phrase du texte.","type":"choix","options":[{"id":"a","texte":"Parce que les collectivités n’ont pas le droit de gérer leurs compétences"},{"id":"b","texte":"Parce que la Corse ne peut pas avoir de collectivité territoriale propre"},{"id":"c","texte":"Parce que la République est indivisible : il n’y a qu’un seul peuple français"},{"id":"d","texte":"Parce que la Constitution interdit toute langue autre que le français"}],"multiple":false},{"enonce":"Touche l’État dont l’organisation ressemble à celle de la France.","aide":"Une seule loi nationale, mais des collectivités élues qui gèrent des compétences.","type":"zone","document":"etats","multiple":false},{"enonce":"Qui exerce chacune de ces compétences en France ?","aide":"Les fonctions régaliennes restent à l’État.","type":"categories","categories":[{"id":"c0","texte":"Collectivité décentralisée"},{"id":"c1","texte":"État"}],"items":[{"id":"i0","texte":"Battre la monnaie"},{"id":"i1","texte":"Rendre la justice"},{"id":"i2","texte":"Assurer la défense"},{"id":"i3","texte":"Gérer le RSA"},{"id":"i4","texte":"Gérer les collèges"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m15"]},"explication":"La mention d’un peuple **corse** a été censurée : elle contredisait l’unité du peuple français."},{"cle":{"type":"choix","ids":["c"]},"explication":"L’**indivisibilité** de la République signifie qu’il n’existe qu’**un seul peuple français**. Cela n’empêche pas la décentralisation."},{"cle":{"type":"zone","ids":["r1c0"]},"explication":"L’État **Y** : des collectivités élues, une loi unique. L’État X est fédéral ; l’État Z est centralisé."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c1","i3":"c0","i4":"c0"}},"explication":"Collèges et RSA relèvent du **département**. Monnaie, justice et défense sont des fonctions **régaliennes**, gardées par l’**État**."}]$ex$::jsonb),
  ('9009928d-f52b-592a-9efb-1496daf3785f'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les étapes de la décentralisation","competence":"se-reperer-temps","situation":"Pour son dossier, un élève dresse la frise des grandes lois de la décentralisation et des langues régionales.","documents":[{"id":"frise","type":"frise","titre":"La décentralisation depuis 1982","source":"Dates du cours","debut":1980,"fin":2020,"pas":10,"evenements":[{"id":"z1","date":1982,"nom":"Loi Defferre"},{"id":"z2","date":2003,"nom":"Acte II"},{"id":"z3","date":2014,"nom":"Loi MAPTAM"},{"id":"z4","date":2015,"nom":"Loi NOTRe"}]}],"questions":[{"enonce":"Touche la loi qui crée les métropoles.","aide":"C’est une loi de 2014.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent la loi Defferre de la loi NOTRe ?","aide":"Soustrais 1982 à 2015.","type":"nombre","unite":"ans"},{"enonce":"Associe chaque étape à ce qu’elle change.","aide":"Chaque étape va un cran plus loin.","type":"association","gauche":[{"id":"g0","texte":"Loi Defferre (1982)"},{"id":"g1","texte":"Acte II (2003-2004)"},{"id":"g2","texte":"Loi MAPTAM (2014)"},{"id":"g3","texte":"Loi NOTRe (2015)"}],"droite":[{"id":"d0","texte":"Les régions de métropole passent de 22 à 13"},{"id":"d1","texte":"Le contrôle de légalité a posteriori remplace la tutelle a priori du préfet"},{"id":"d2","texte":"La décentralisation entre dans la Constitution"},{"id":"d3","texte":"Création des métropoles"}]}]}$ex$::jsonb,
