  ('9009928d-f52b-592a-9efb-1496daf3785f'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"De 22 à 13 régions","competence":"lire-carte","situation":"La loi NOTRe de 2015 a réduit le nombre de régions de la France métropolitaine. Un élève regarde la carte pour repérer celles qui ont fusionné.","documents":[{"id":"carte","type":"carte","titre":"Les 13 régions de métropole depuis 2016","source":"Fond de carte du guide","fond":"france","regionsCliquables":true,"regions":[{"code":"GES","teinte":"violet","motif":"clair"},{"code":"HDF","teinte":"violet","motif":"clair"},{"code":"NOR","teinte":"violet","motif":"clair"},{"code":"NAQ","teinte":"violet","motif":"clair"},{"code":"OCC","teinte":"violet","motif":"clair"},{"code":"ARA","teinte":"violet","motif":"clair"},{"code":"BFC","teinte":"violet","motif":"clair"},{"code":"BRE","teinte":"gris","motif":"hachures"},{"code":"PDL","teinte":"gris","motif":"hachures"},{"code":"CVL","teinte":"gris","motif":"hachures"},{"code":"IDF","teinte":"gris","motif":"hachures"},{"code":"PAC","teinte":"gris","motif":"hachures"},{"code":"COR","teinte":"gris","motif":"hachures"}],"legende":[{"teinte":"violet","motif":"clair","texte":"Région issue d’une fusion (2016)"},{"teinte":"gris","motif":"hachures","texte":"Région non fusionnée"}]}],"questions":[{"enonce":"Parmi les régions issues d’une fusion, touche celle qui borde l’Allemagne.","aide":"Cherche la région fusionnée à l’est de la France, le long du Rhin.","type":"zone","document":"carte","multiple":false},{"enonce":"Combien de régions de métropole n’ont pas fusionné ?","aide":"Compte les régions hachurées.","type":"nombre","unite":"régions"},{"enonce":"La métropole comptait 22 régions avant 2016 et en compte 13 aujourd’hui. De combien a-t-elle diminué ?","aide":"Soustrais le nombre actuel au nombre d’avant.","type":"nombre","unite":"régions"},{"enonce":"Que fait aussi la loi NOTRe de 2015, outre la réduction du nombre de régions ?","aide":"Le nom de la loi signifie « Nouvelle organisation territoriale de la République ».","type":"choix","options":[{"id":"a","texte":"Elle inscrit les langues régionales dans la Constitution française"},{"id":"b","texte":"Elle supprime le contrôle de légalité du préfet sur les actes locaux"},{"id":"c","texte":"Elle clarifie les compétences des collectivités territoriales"},{"id":"d","texte":"Elle crée les métropoles, que la loi MAPTAM n’avait pas prévues"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["GES"]},"explication":"Le **Grand Est**, issu d’Alsace, de Champagne-Ardenne et de Lorraine, borde l’Allemagne le long du Rhin."},{"cle":{"type":"nombre","valeur":6,"tolerance":0},"affichage":"6 régions","explication":"Six régions n’ont pas fusionné : Bretagne, Pays de la Loire, Centre-Val de Loire, Île-de-France, Provence-Alpes-Côte d’Azur et Corse."},{"cle":{"type":"nombre","valeur":9,"tolerance":0},"affichage":"9 régions","explication":"22 − 13 = **9 régions** de moins, grâce aux fusions de la loi NOTRe."},{"cle":{"type":"choix","ids":["c"]},"explication":"La loi **NOTRe** clarifie les compétences des collectivités et réduit le nombre de régions. Les métropoles viennent de la loi MAPTAM (2014)."}]$ex$::jsonb),
  ('9009928d-f52b-592a-9efb-1496daf3785f'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Une République, des statuts différents","competence":"analyser-document","situation":"Quatre élèves de première, d’origines différentes, comparent leurs statuts territoriaux. Ils lisent aussi ce que la Constitution dit des langues.","documents":[{"id":"statuts","type":"tableau","titre":"Trois régimes de l’outre-mer","source":"Résumé du cours","colonnes":["Régime","Ce qu’il prévoit"],"lignes":[["Article 73","Les lois de la République s’appliquent, avec des adaptations possibles."],["Article 74","Un statut particulier fixé par loi organique, avec une part d’autonomie."],["Titre XIII","Un accord de 1998 : citoyenneté calédonienne, « lois du pays », transferts de compétences."]],"enteteLignes":true},{"id":"eleves","type":"texte","genre":"source","titre":"Quatre élèves","source":"Personnages imaginés pour l’exercice","blocs":["Nina vit à Saint-Denis, à La Réunion.","Tevai vit à Papeete, en Polynésie française.","Marie vit à Nouméa, en Nouvelle-Calédonie.","Léo vit à Fort-de-France, en Martinique."]}],"questions":[{"enonce":"Touche la case qui évoque des « lois du pays ».","aide":"Seul un régime parle de lois propres au territoire.","type":"zone","document":"statuts","multiple":false},{"enonce":"Classe chaque élève selon le régime de son territoire.","aide":"Les départements et régions d’outre-mer relèvent de l’article 73.","type":"categories","categories":[{"id":"c0","texte":"Article 73"},{"id":"c1","texte":"Article 74"},{"id":"c2","texte":"Titre XIII"}],"items":[{"id":"i0","texte":"Nina (La Réunion)"},{"id":"i1","texte":"Marie (Nouvelle-Calédonie)"},{"id":"i2","texte":"Tevai (Polynésie française)"},{"id":"i3","texte":"Léo (Martinique)"}]},{"enonce":"Pourquoi ces statuts différents ne contredisent-ils pas l’indivisibilité de la République ?","aide":"L’unité n’exige pas l’uniformité.","type":"choix","options":[{"id":"a","texte":"Chaque territoire a ses lois sans aucun contrôle de l’État"},{"id":"b","texte":"Les territoires d’outre-mer ne font pas partie de la République"},{"id":"c","texte":"L’indivisibilité est une formule sans aucune portée juridique"},{"id":"d","texte":"L’unité juridique demeure : la loi commune s’applique, même adaptée"}],"multiple":false},{"enonce":"Associe chaque article de la Constitution à ce qu’il dispose.","aide":"Cherche l’article qui parle de langue et celui qui parle de patrimoine.","type":"association","gauche":[{"id":"g0","texte":"Article 2"},{"id":"g1","texte":"Article 75-1"},{"id":"g2","texte":"Article 72"}],"droite":[{"id":"d0","texte":"Les langues régionales appartiennent au patrimoine de la France"},{"id":"d1","texte":"Les collectivités s’administrent librement par des conseils élus"},{"id":"d2","texte":"La langue de la République est le français"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c1"]},"explication":"Les « **lois du pays** » relèvent du titre XIII, l’accord de Nouméa (1998)."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c2","i2":"c1","i3":"c0"}},"explication":"La **Réunion** et la **Martinique** relèvent de l’article 73 ; la **Polynésie française** de l’article 74 ; la **Nouvelle-Calédonie** du titre XIII."},{"cle":{"type":"choix","ids":["d"]},"explication":"L’unité de la Nation n’exige pas l’**uniformité** des territoires : elle exige que la loi commune s’applique partout, y compris quand elle s’adapte."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"Article **2** : le français. Article **75-1**, ajouté en 2008 : les langues régionales appartiennent au patrimoine. Article **72** : libre administration."}]$ex$::jsonb),
  ('f4ef57a8-9602-55b3-ae15-dbec3c034cb5'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Trois jeunes, trois façons d’être français","competence":"analyser-document","situation":"Trois jeunes ont un lien avec la France. Une élève de première cherche, pour chacun, comment il est ou deviendra français.","documents":[{"id":"jeunes","type":"tableau","titre":"Trois situations","source":"Personnes imaginées pour l’exercice","colonnes":["Personne","Naissance","Parents"],"lignes":[["Léo","Né à Tunis","Mère française, père tunisien"],["Naïma","Née à Marseille","Père étranger né à Marseille, mère étrangère née à l’étranger"],["Tom, 17 ans","Né à Nantes, résidant en France sans interruption","Parents étrangers nés à l’étranger"]],"enteteLignes":true}],"questions":[{"enonce":"Associe chaque voie d’accès à la nationalité à la personne concernée.","aide":"Le droit du sang suit les parents ; le double droit du sol exige un parent né en France.","type":"association","gauche":[{"id":"g0","texte":"Droit du sang"},{"id":"g1","texte":"Double droit du sol"},{"id":"g2","texte":"Droit du sol à 18 ans"}],"droite":[{"id":"d0","texte":"Tom"},{"id":"d1","texte":"Léo"},{"id":"d2","texte":"Naïma"}]},{"enonce":"Touche la personne française dès sa naissance parce qu’un de ses parents est lui-même né en France.","aide":"Compare le lieu de naissance des parents.","type":"zone","document":"jeunes","multiple":false},{"enonce":"À 18 ans, combien d’années Tom aura-t-il passées en France depuis l’âge de 11 ans, en y résidant sans interruption ?","aide":"Soustrais 11 à 18.","type":"nombre","unite":"ans"}]}$ex$::jsonb,
