  ('f4ef57a8-9602-55b3-ae15-dbec3c034cb5'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Aldo vote-t-il à Lyon ?","competence":"lire-tableau","situation":"Aldo, Italien installé à Lyon, est citoyen de l’Union européenne. Une classe compare ses droits à ceux d’une Française et d’une résidente étrangère hors Union.","documents":[{"id":"droits","type":"tableau","titre":"Qui peut voter en France ?","source":"Personnes imaginées pour l’exercice","colonnes":["Résident en France","Municipales","Européennes","Présidentielle"],"lignes":[["Chloé, française","Oui","Oui","Oui"],["Aldo, italien, citoyen de l’Union","Oui","Oui","Non"],["Binta, de nationalité sénégalaise","Non","Non","Non"]],"enteteLignes":true},{"id":"situations","type":"texte","genre":"source","titre":"Deux situations","source":"Situations imaginées pour l’exercice","blocs":["Une initiative citoyenne européenne est lancée. L’Union compte 27 États membres. Il faut recueillir un million de signatures, venant d’au moins un quart des États.","Aldo perd ses papiers dans un pays hors de l’Union où l’Italie n’a pas d’ambassade. L’ambassade de France accepte de l’aider."]}],"questions":[{"enonce":"Touche les deux cases qui montrent que la citoyenneté n’est pas toujours attachée à la nationalité.","aide":"Cherche un étranger qui vote malgré tout.","type":"zone","document":"droits","multiple":true},{"enonce":"Combien d’États au minimum doivent apporter des signatures ? Un quart de 27, arrondi à l’entier supérieur.","aide":"Divise 27 par 4, puis arrondis vers le haut.","type":"nombre","unite":"États"},{"enonce":"Quel droit de la citoyenneté européenne l’aide de l’ambassade de France illustre-t-elle ?","aide":"Aldo est à l’étranger, hors de l’Union, et demande de l’aide.","type":"choix","options":[{"id":"a","texte":"Le droit de voter aux élections européennes"},{"id":"b","texte":"La protection consulaire par tout État membre"},{"id":"c","texte":"Le droit de circuler et de séjourner dans toute l’Union"},{"id":"d","texte":"Le droit de pétition adressé au Parlement européen"}],"multiple":false},{"enonce":"Complète la distinction à retenir.","aide":"Voter et être élu sont des droits politiques.","type":"trous","segments":["La ",0," est un lien juridique avec un État ; la ",1," y ajoute des droits politiques."],"banque":["naturalisation","citoyenneté","identité","nationalité"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1","r1c2"]},"explication":"Aldo n’est pas français mais vote aux **municipales** et aux **européennes** : c’est l’exception de la citoyenneté européenne. La présidentielle lui reste fermée."},{"cle":{"type":"nombre","valeur":7,"tolerance":0},"affichage":"7 États","explication":"27 ÷ 4 = 6,75, donc au moins **7 États** (on ne peut pas avoir 6,75 États)."},{"cle":{"type":"choix","ids":["b"]},"explication":"La **protection consulaire** permet à un citoyen européen de demander l’aide de l’ambassade de n’importe quel État membre."},{"cle":{"type":"trous","trous":[["nationalite"],["citoyennete"]]},"affichage":"nationalité · citoyenneté","explication":"La **nationalité** est un lien juridique ; la **citoyenneté** y ajoute des droits politiques : voter, être élu."}]$ex$::jsonb),
  ('f4ef57a8-9602-55b3-ae15-dbec3c034cb5'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Karim, Maria et la cérémonie d’accueil","competence":"argumenter","situation":"Karim et Maria vivent en France et envisagent de devenir français. Une élève de première calcule à quelle date chacun pourra en faire la demande.","documents":[{"id":"parcours","type":"texte","genre":"recit","titre":"Deux parcours","source":"Personnages imaginés pour l’exercice","blocs":["Karim est arrivé en France en 2018 avec un titre de séjour régulier. Il y réside sans interruption et parle bien le français.","Maria s’est mariée en 2021 avec Julien, de nationalité française. Ils vivent ensemble depuis le mariage."]},{"id":"ceremonie","type":"fiche","modele":"invitation","entete":"Cérémonie d’accueil dans la citoyenneté française","sousTitre":"Invitation imaginée pour l’exercice","emoji":"🎉","lignes":[{"texte":"Accueil par le préfet"},{"texte":"Remise de la charte des droits et devoirs du citoyen français","id":"z1"},{"texte":"Verre de l’amitié"}]}],"questions":[{"enonce":"Touche ce que reçoit chaque nouveau citoyen lors de la cérémonie.","aide":"Cherche un document remis aux invités.","type":"zone","document":"ceremonie","multiple":false},{"enonce":"À partir de quelle année Karim peut-il en principe demander la naturalisation, après cinq ans de résidence régulière ?","aide":"Ajoute cinq ans à son année d’arrivée.","type":"nombre","unite":"année"},{"enonce":"Classe chaque élément.","aide":"Les droits politiques relèvent de la citoyenneté.","type":"categories","categories":[{"id":"c0","texte":"Nationalité"},{"id":"c1","texte":"Citoyenneté"}],"items":[{"id":"i0","texte":"Voter à une élection"},{"id":"i1","texte":"Avoir la nationalité française"},{"id":"i2","texte":"Un lien juridique entre une personne et l’État"},{"id":"i3","texte":"Pouvoir être élu"}]},{"enonce":"À partir de quelle année Maria peut-elle devenir française par déclaration, après quatre ans de vie commune ?","aide":"Ajoute quatre ans à l’année du mariage.","type":"nombre","unite":"année"},{"enonce":"Une fois française, que lui apporte en plus la citoyenneté européenne ?","aide":"Elle complète la citoyenneté nationale sans la remplacer.","type":"choix","options":[{"id":"a","texte":"La disparition de sa citoyenneté nationale française"},{"id":"b","texte":"Un droit de vote dans toutes les élections de l’Union"},{"id":"c","texte":"Le droit de voter à la présidentielle de n’importe quel État"},{"id":"d","texte":"La libre circulation et le séjour dans toute l’Union"}],"multiple":false}]}$ex$::jsonb,
