  ('65ff5d37-8556-5758-ace0-d6e503f49374'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le calendrier des cérémonies de Valmy-les-Bois","competence":"analyser-document","situation":"La mairie de Valmy-les-Bois, commune imaginaire, a affiché son calendrier de cérémonies. Une élève cherche ce que chaque date rappelle.","documents":[{"id":"calendrier","type":"fiche","modele":"affiche","entete":"Cérémonies de l’année","sousTitre":"Affiche imaginée pour l’exercice","emoji":"🏛️","lignes":[{"texte":"27 janvier — salle Marianne","id":"z1"},{"texte":"8 mai — place de la Mairie","id":"z2"},{"texte":"10 mai — jardin des Vents","id":"z3"},{"texte":"18 juin — mât des couleurs","id":"z4"},{"texte":"11 novembre — monument aux morts","id":"z5"}]}],"questions":[{"enonce":"Touche la cérémonie qui rappelle l’appel du général de Gaulle.","aide":"Cet appel date de juin 1940.","type":"zone","document":"calendrier","multiple":false},{"enonce":"Associe chaque date à ce qu’elle rappelle.","aide":"Deux dates parlent de la guerre, deux de mémoires particulières.","type":"association","gauche":[{"id":"g0","texte":"11 novembre"},{"id":"g1","texte":"8 mai"},{"id":"g2","texte":"27 janvier"},{"id":"g3","texte":"10 mai"}],"droite":[{"id":"d0","texte":"Les victimes de la Shoah"},{"id":"d1","texte":"La victoire de 1945"},{"id":"d2","texte":"La traite, l’esclavage et leurs abolitions"},{"id":"d3","texte":"L’armistice de 1918 et tous les morts pour la France"}]},{"enonce":"Quelle différence y a-t-il entre une commémoration et un cours d’histoire ?","aide":"La mémoire est sélective, l’histoire est critique.","type":"choix","options":[{"id":"a","texte":"La commémoration est fondée sur des archives, le cours sur des souvenirs"},{"id":"b","texte":"La commémoration n’a aucun rapport avec le passé, le cours n’y a que rapport"},{"id":"c","texte":"La commémoration est écrite par des historiens, le cours est écrit par des élèves"},{"id":"d","texte":"La commémoration choisit ce qu’elle rappelle, l’histoire est critique et fondée sur des sources"}],"multiple":false}]}$ex$::jsonb,
