   $ex${"titre":"Les lois mémorielles en débat","competence":"argumenter","situation":"Une classe prépare un débat sur les lois mémorielles et sur la formule « devoir de mémoire ». Elle part d’une frise puis des interventions de quatre élèves.","documents":[{"id":"frise","type":"frise","titre":"Lois et textes de mémoire","source":"Dates du cours","debut":1990,"fin":2025,"pas":5,"evenements":[{"id":"z1","date":1990,"nom":"Loi Gayssot"},{"id":"z2","date":2001,"nom":"Loi Taubira"},{"id":"z3","date":2012,"nom":"Décision du Conseil"},{"id":"z4","date":2021,"nom":"Portraits de France"}]},{"id":"debat","type":"texte","genre":"source","titre":"Le débat de la classe","source":"Interventions écrites pour l’exercice","blocs":["Inès : « Dire “devoir de mémoire”, c’est transformer le passé en obligation imposée à chacun. »","Mathis : « Si on abandonne cette formule, on laisse le champ libre à l’oubli. »","Sana : « Une formule aussi large fige le passé : on récite au lieu de comprendre. »","Paul : « Sans cette formule, plus personne ne se sentirait responsable de transmettre. »"]}],"questions":[{"enonce":"Combien d’années séparent la loi Taubira de la décision du Conseil constitutionnel sur le génocide arménien ?","aide":"Soustrais 2001 à 2012.","type":"nombre","unite":"ans"},{"enonce":"Touche la date où le Conseil constitutionnel censure la loi pénalisant la négation du génocide arménien.","aide":"Ce n’est ni une loi, ni un recueil : cherche la décision d’un juge.","type":"zone","document":"frise","multiple":false},{"enonce":"Classe chaque intervention du débat.","aide":"Qui juge la formule trop large, et qui craint l’oubli ?","type":"categories","categories":[{"id":"c0","texte":"Contre la formule"},{"id":"c1","texte":"Pour la formule"}],"items":[{"id":"i0","texte":"Intervention de Mathis"},{"id":"i1","texte":"Intervention de Paul"},{"id":"i2","texte":"Intervention de Sana"},{"id":"i3","texte":"Intervention d’Inès"}]},{"enonce":"Pourquoi des historiens critiquent-ils certaines lois mémorielles ?","aide":"Distingue le rôle du législateur et celui des historiens.","type":"choix","options":[{"id":"a","texte":"Parce qu’elles ne concernent que des événements récents"},{"id":"b","texte":"Parce qu’elles sont toujours censurées par le Conseil constitutionnel"},{"id":"c","texte":"Parce qu’elles interdisent l’accès aux archives de l’État"},{"id":"d","texte":"Parce qu’il n’appartient pas au législateur d’écrire l’histoire"}],"multiple":false}]}$ex$::jsonb,
