{"id":"c0","texte":"Le droit"},{"id":"c1","texte":"La science historique"},{"id":"c2","texte":"La politique mémorielle"}],"items":[{"id":"i0","texte":"Une décision du Conseil constitutionnel de 2012"},{"id":"i1","texte":"Un travail d’historiens fondé sur des archives"},{"id":"i2","texte":"Un débat scientifique entre sources contradictoires"},{"id":"i3","texte":"Une loi qui punit la contestation de crimes contre l’humanité"},{"id":"i4","texte":"Une cérémonie le 8 mai devant le monument aux morts"}]},{"enonce":"Touche la case qui décrit qui peut faire partie de la Nation dans la conception B.","aide":"Cherche la ligne « Qui peut en faire partie » et la colonne de la conception B.","type":"zone","document":"conceptions","multiple":false}]}$ex$::jsonb,
