ne","de":[200,100],"a":[270,100],"teinte":"gris"},{"forme":"ligne","de":[270,100],"a":[270,170],"teinte":"gris"},{"forme":"ligne","de":[270,170],"a":[200,170],"teinte":"gris"},{"forme":"ligne","de":[200,170],"a":[200,100],"teinte":"gris"},{"forme":"ligne","de":[230,70],"a":[300,70],"teinte":"gris"},{"forme":"ligne","de":[300,70],"a":[300,140],"teinte":"gris"},{"forme":"ligne","de":[200,100],"a":[230,70],"teinte":"gris"},{"forme":"ligne","de":[270,100],"a":[300,70],"teinte":"gris"},{"forme":"ligne","de":[270,170],"a":[300,140],"teinte":"gris"},{"forme":"ligne","de":[200,170],"a":[230,140],"teinte":"gris","style":"pointilles"},{"forme":"ligne","de":[300,140],"a":[230,140],"teinte":"gris","style":"pointilles"},{"forme":"ligne","de":[230,140],"a":[230,70],"teinte":"gris","style":"pointilles"},{"forme":"cercle","cx":200,"cy":100,"r":7,"teinte":"violet","motif":"plein"},{"forme":"cercle","cx":270,"cy":100,"r":7,"teinte":"violet","motif":"plein"},{"forme":"cercle","cx":270,"cy":170,"r":7,"teinte":"violet","motif":"plein"},{"forme":"cercle","cx":200,"cy":170,"r":7,"teinte":"violet","motif":"plein"},{"forme":"cercle","cx":230,"cy":70,"r":7,"teinte":"violet","motif":"plein"},{"forme":"cercle","cx":300,"cy":70,"r":7,"teinte":"violet","motif":"plein"},{"forme":"cercle","cx":300,"cy":140,"r":7,"teinte":"violet","motif":"plein"},{"forme":"cercle","cx":230,"cy":140,"r":7,"teinte":"violet","motif":"plein"},{"forme":"cercle","cx":235,"cy":135,"r":7,"teinte":"jaune","motif":"plein"},{"forme":"cercle","cx":265,"cy":105,"r":7,"teinte":"jaune","motif":"plein"},{"forme":"cercle","cx":215,"cy":120,"r":7,"teinte":"jaune","motif":"plein"},{"forme":"cercle","cx":285,"cy":120,"r":7,"teinte":"jaune","motif":"plein"},{"forme":"cercle","cx":250,"cy":85,"r":7,"teinte":"jaune","motif":"plein"},{"forme":"cercle","cx":250,"cy":155,"r":7,"teinte":"jaune","motif":"plein"},{"forme":"texte","x":90,"y":30,"texte":"Maille 1","ancre":"milieu"},{"forme":"texte","x":260,"y":30,"texte":"Maille 2","ancre":"mil