  ('f6faf72e-98a5-5d76-8274-519620c30a2e'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La masse volumique du cuivre, calculée sur une maille","competence":"calculer","situation":"Samir veut prévoir la masse volumique du cuivre sans le peser : il part de la maille du cristal et la compare à la valeur mesurée par un laboratoire.","documents":[{"id":"donnees","type":"tableau","titre":"Données sur le cuivre","colonnes":["Grandeur","Valeur"],"lignes":[["Structure","cubique à faces centrées"],["Côté de la maille a","0,361 nm"],["Atomes par maille","4"],["Masse molaire M","63,5 g/mol"],["Nombre d’Avogadro","6,02 × 10²³ mol⁻¹"]],"enteteLignes":true,"source":"Valeurs arrondies. 1 nm³ = 10⁻²¹ cm³"},{"id":"mesures","type":"tableau","titre":"Masses volumiques mesurées","colonnes":["Métal","Maille","ρ (g/cm³)"],"lignes":[["Cuivre","faces centrées","8,96"],["Fer","cubique centrée","7,87"],["Aluminium","faces centrées","2,70"]],"enteteLignes":true,"source":"Valeurs arrondies"}],"questions":[{"enonce":"Touche la masse volumique mesurée du cuivre.","aide":"Ligne du cuivre, dernière colonne.","type":"zone","document":"mesures","multiple":false},{"enonce":"Quelle est la masse des 4 atomes d’une maille, en 10⁻²² g ? (4 × M / Nₐ, un chiffre après la virgule suffit ; réponds à 0,05 près.)","aide":"La masse d’un atome vaut M divisée par le nombre d’Avogadro ; multiplie par 4.","type":"nombre"},{"enonce":"Quel est le volume de la maille a³, en 10⁻²³ cm³ ? (à 0,05 près)","aide":"Calcule 0,361³ en nm³, puis convertis avec 1 nm³ = 10⁻²¹ cm³.","type":"nombre"},{"enonce":"Quelle masse volumique ρ = masse de la maille ÷ volume de la maille obtiens-tu, en g/cm³ ? (à 0,1 près)","aide":"Divise 4,22 × 10⁻²² par 4,70 × 10⁻²³ : la puissance de 10 se simplifie en multipliant par 10.","type":"nombre","unite":"g/cm³"},{"enonce":"Que dire de l’écart entre cette valeur calculée et la valeur mesurée ?","aide":"Compare 8,97 à 8,96.","type":"choix","options":[{"id":"a","texte":"Il est nul : un calcul de maille donne toujours exactement la mesure"},{"id":"b","texte":"Il est de 50 % : on a oublié la moitié des atomes de la maille"},{"id":"c","texte":"Il dépasse 10 % : le modèle de maille est trop grossier pour ce métal"},{"id":"d","texte":"Il est inférieur à 1 % : le modèle de maille décrit très bien le cristal"}],"multiple":false}]}$ex$::jsonb,
