  ('2f65b9bd-356e-5b44-9ce9-d02b235d98d7'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Pourquoi ne voit-on pas la membrane ?","competence":"raisonner","situation":"Au lycée, Lou observe des cellules au microscope optique. Elle voit bien les cellules et les bactéries, mais jamais la membrane qui les entoure. Elle compare les tailles.","documents":[{"id":"tailles","type":"tableau","titre":"Quelques ordres de grandeur","colonnes":["Objet","Taille"],"lignes":[["Cellule animale (exemple)","50 µm"],["Bactérie","1 µm"],["Plus petit détail visible au microscope optique","0,2 µm"],["Épaisseur de la membrane plasmique","7,5 nm"]],"enteteLignes":true,"source":"Ordres de grandeur. 1 µm = 1 000 nm"}],"questions":[{"enonce":"Touche la taille de l’objet le plus petit du tableau.","aide":"Attention aux unités : le nanomètre est mille fois plus petit que le micromètre.","type":"zone","document":"tailles","multiple":false},{"enonce":"Combien de bactéries de 1 µm alignées bout à bout faut-il pour traverser une cellule animale de 50 µm ?","aide":"Divise 50 µm par 1 µm.","type":"nombre"},{"enonce":"Exprime en nanomètres le plus petit détail visible au microscope optique (0,2 µm).","aide":"1 µm = 1 000 nm.","type":"nombre","unite":"nm"},{"enonce":"Combien de fois la membrane (7,5 nm) est-elle plus fine que ce que le microscope optique distingue ? Arrondis à l’unité.","aide":"Divise 200 nm par 7,5 nm.","type":"nombre"},{"enonce":"Quel instrument a donc été nécessaire pour observer la membrane plasmique ?","aide":"Grossir une image ne la rend pas plus précise : c’est la résolution qui compte.","type":"choix","options":[{"id":"a","texte":"Le microscope électronique, dont la résolution est bien meilleure"},{"id":"b","texte":"Une loupe de grande taille posée sur la lame de verre"},{"id":"c","texte":"Un microscope optique avec un grossissement plus fort encore"},{"id":"d","texte":"Un microscope optique avec un éclairage plus puissant"}],"multiple":false}]}$ex$::jsonb,
