  ('d1eae4d4-ed1d-53e7-9419-4a0a80060455'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Le bilan de matière d’une feuille","competence":"calculer","situation":"Une feuille fabrique du glucose à partir de dioxyde de carbone et d’eau. Yanis calcule les masses mises en jeu pour une mole de glucose produite.","documents":[{"id":"masses","type":"tableau","titre":"Masses molaires atomiques","colonnes":["Atome","Masse molaire (g/mol)"],"lignes":[["Carbone C",12],["Hydrogène H",1],["Oxygène O",16]],"enteteLignes":true,"source":"Valeurs arrondies"}],"questions":[{"enonce":"Complète l’équation bilan de la photosynthèse.","aide":"Il faut de l’eau en entrée, et un gaz que les plantes rejettent en sortie.","type":"trous","segments":["6 CO₂ + 6 ",0," → C₆H₁₂O₆ + 6 ",1],"banque":["H₂O","O₂","CO","N₂","H₂"]},{"enonce":"Calcule la masse molaire du glucose C₆H₁₂O₆, en g/mol.","aide":"6 atomes de C, 12 de H, 6 de O : additionne leurs masses.","type":"nombre","unite":"g/mol"},{"enonce":"Une mole de glucose produite s’accompagne de 6 moles de dioxygène O₂. Quelle masse de dioxygène est rejetée, en g ?","aide":"M(O₂) = 2 × 16 g/mol ; multiplie par 6.","type":"nombre","unite":"g"},{"enonce":"Pour cette même mole de glucose, quelle masse d’eau est consommée (6 moles d’H₂O), en g ?","aide":"M(H₂O) = 2 × 1 + 16 g/mol.","type":"nombre","unite":"g"},{"enonce":"La feuille a consommé 264 g de CO₂ et 108 g d’eau, et produit 180 g de glucose et 192 g de dioxygène. Que constate-t-on ?","aide":"Additionne d’un côté, puis de l’autre.","type":"choix","options":[{"id":"a","texte":"Les produits sont plus massifs que les réactifs : la lumière apporte de la masse"},{"id":"b","texte":"Les masses ne peuvent pas être comparées : les états physiques diffèrent"},{"id":"c","texte":"Les réactifs et les produits ont la même masse, 372 g : la matière se conserve"},{"id":"d","texte":"Les réactifs sont plus massifs que les produits : du carbone s’est perdu"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"trous","trous":[["h o"],["o"]]},"affichage":"H₂O · O₂","explication":"**6 CO₂ + 6 H₂O → C₆H₁₂O₆ + 6 O₂**, en présence de lumière et de chlorophylle."},{"cle":{"type":"nombre","valeur":180,"tolerance":0},"affichage":"180 g/mol","explication":"6 × 12 + 12 × 1 + 6 × 16 = 72 + 12 + 96 = **180 g/mol**."},{"cle":{"type":"nombre","valeur":192,"tolerance":0},"affichage":"192 g","explication":"6 × (2 × 16) = 6 × 32 = **192 g** de dioxygène."},{"cle":{"type":"nombre","valeur":108,"tolerance":0},"affichage":"108 g","explication":"6 × 18 = **108 g** d’eau."},{"cle":{"type":"choix","ids":["c"]},"explication":"264 + 108 = 372 et 180 + 192 = 372 : **la masse se conserve**. Les atomes sont les mêmes, simplement réarrangés."}]$ex$::jsonb),
  ('d1eae4d4-ed1d-53e7-9419-4a0a80060455'::uuid, 3, 3, 15, 50, 5,
