  ('d4f4f580-32d1-5e04-8307-0384549f0a82'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Un puits, une ombre et la Terre entière","competence":"observer-schema","situation":"Vers 240 avant J.-C., Ératosthène apprend qu’à Syène, au solstice, le Soleil éclaire le fond d’un puits. Le même jour, à Alexandrie, un gnomon fait une ombre. On prendra 1 stade ≈ 0,16 km.","documents":[{"id":"eratosthene","type":"schema","titre":"La méthode d’Ératosthène","largeur":320,"hauteur":270,"elements":[{"forme":"cercle","cx":160,"cy":170,"r":80,"teinte":"ciel","motif":"clair"},{"forme":"ligne","de":[160,170],"a":[160,90],"teinte":"gris","style":"pointilles"},{"forme":"ligne","de":[160,170],"a":[200,100.7],"teinte":"gris","style":"pointilles"},{"forme":"ligne","de":[160,20],"a":[160,84],"fleche":"fin","teinte":"jaune"},{"forme":"ligne","de":[211,20],"a":[211,80],"fleche":"fin","teinte":"jaune"},{"forme":"ligne","de":[200,100.7],"a":[211,81.7],"teinte":"encre"},{"forme":"cercle","cx":160,"cy":90,"r":6,"teinte":"corail","motif":"plein","id":"z1","zone":true},{"forme":"cercle","cx":200,"cy":100.7,"r":6,"teinte":"corail","motif":"plein","id":"z2","zone":true},{"forme":"texte","x":148,"y":86,"texte":"Syène","ancre":"fin"},{"forme":"texte","x":218,"y":112,"texte":"Alexandrie","ancre":"debut"},{"forme":"etiquette","x":252,"y":160,"texte":"7,2°","vers":[172,138]},{"forme":"texte","x":160,"y":12,"texte":"Rayons du Soleil, parallèles","ancre":"milieu","taille":"petit","italique":true},{"forme":"texte","x":160,"y":262,"texte":"Schéma non à l’échelle : l’angle réel est bien plus petit que dessiné.","ancre":"milieu","taille":"petit","italique":true}]}],"questions":[{"enonce":"Touche la ville où le Soleil est au zénith et éclaire le fond du puits.","aide":"Là, les rayons arrivent à la verticale du lieu : le long du rayon de la Terre.","type":"zone","document":"eratosthene","multiple":false},{"enonce":"L’angle de 7,2° est une partie du tour complet de 360°. Combien de fois entre-t-il dans le tour complet ?","aide":"Divise 360 par 7,2.","type":"nombre"},{"enonce":"Les deux villes sont séparées d’environ 5 000 stades. Quelle est la circonférence de la Terre, en stades ?","aide":"Multiplie la distance entre les villes par le nombre de fois que l’arc entre dans le tour complet.","type":"nombre","unite":"stades"},{"enonce":"Avec 1 stade ≈ 0,16 km, on trouve 40 000 km. La valeur moderne est 40 075 km. Que penser de ce résultat ?","aide":"Calcule l’écart 75 km sur 40 075 km.","type":"choix","options":[{"id":"a","texte":"La comparaison n’a pas de sens : les unités antiques sont inconnues"},{"id":"b","texte":"L’erreur est inférieure à 1 % : un résultat remarquable pour un bâton et une ombre"},{"id":"c","texte":"Il n’y a aucune erreur : les deux valeurs sont rigoureusement égales"},{"id":"d","texte":"L’erreur dépasse 20 % : la méthode ne marche qu’à peu près"}],"multiple":false}]}$ex$::jsonb,
