  ('d4f4f580-32d1-5e04-8307-0384549f0a82'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Du méridien au mètre","competence":"calculer","situation":"En 1791, on décide de définir une nouvelle unité de longueur à partir de la Terre elle-même. Léa refait le calcul à partir de l’arc de méridien mesuré entre Dunkerque et Barcelone.","documents":[{"id":"texte","type":"texte","genre":"source","titre":"La définition du mètre","blocs":["En 1791, l’Académie des sciences propose de définir le mètre comme la dix-millionième partie du quart du méridien terrestre.","Pour connaître cette longueur, Delambre et Méchain mesurent un arc de méridien entre Dunkerque et Barcelone, puis en déduisent le quart tout entier."],"source":"Texte écrit pour l’exercice, d’après l’histoire du système métrique"},{"id":"donnees","type":"tableau","titre":"Les données","colonnes":["Donnée","Valeur"],"lignes":[["Latitude de Dunkerque","51° N"],["Latitude de Barcelone","41,4° N"],["Rayon moyen de la Terre R","6 371 km"]],"enteteLignes":true,"source":"Valeurs arrondies"}],"questions":[{"enonce":"Touche la latitude de Barcelone.","aide":"Repère la ligne qui parle de Barcelone.","type":"zone","document":"donnees","multiple":false},{"enonce":"Quel angle α au centre de la Terre l’arc Dunkerque–Barcelone sous-tend-il, en degrés ? (les deux villes sont sur le même méridien)","aide":"Soustrais les deux latitudes.","type":"nombre","unite":"°"},{"enonce":"Pour appliquer L = R × α, dans quelle unité l’angle α doit-il être exprimé ?","aide":"La formule L = R × α n’est juste que pour une unité d’angle précise, définie par le rapport arc / rayon.","type":"choix","options":[{"id":"a","texte":"En minutes d’arc"},{"id":"b","texte":"En degrés"},{"id":"c","texte":"En radians"},{"id":"d","texte":"En grades, comme en topographie"}],"multiple":false},{"enonce":"Quelle est la longueur de l’arc Dunkerque–Barcelone, en km ? (à 3 km près)","aide":"Multiplie R = 6 371 km par α ≈ 0,1676 rad.","type":"nombre","unite":"km"},{"enonce":"Le quart du méridien correspond à un angle de 90° (du pôle à l’équateur). Quelle est sa longueur, en km ? (à 20 km près)","aide":"90° = π ÷ 2 rad ≈ 1,571 rad ; multiplie par R.","type":"nombre","unite":"km"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"Barcelone est à **41,4° N** : c’est la borne sud de l’arc mesuré."},{"cle":{"type":"nombre","valeur":9.6,"tolerance":0.05},"affichage":"9,6 °","explication":"51 − 41,4 = **9,6°**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Il faut des **radians** : α(rad) = α(°) × π ÷ 180. Ici, 9,6 × π ÷ 180 ≈ 0,1676 rad."},{"cle":{"type":"nombre","valeur":1067,"tolerance":3},"affichage":"1067 km","explication":"6 371 × 0,1676 ≈ **1 067 km**."},{"cle":{"type":"nombre","valeur":10007,"tolerance":20},"affichage":"10 007 km","explication":"6 371 × 1,571 ≈ **10 007 km**, soit environ 10⁷ m : sa dix-millionième partie vaut bien **1 m**."}]$ex$::jsonb),
  ('d4f4f580-32d1-5e04-8307-0384549f0a82'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Paris–New York : le trajet qui monte au nord","competence":"lire-carte","situation":"Sur le planisphère du hall d’embarquement, le vol Paris–New York semble faire un détour par le nord. Sam compare deux trajets possibles : l’un de longueur minimale, l’autre à cap constant. L’avion vole à 900 km/h.","documents":[{"id":"carte","type":"carte","titre":"Deux trajets Paris–New York","fond":"monde","cadrage":[-85,30,15,65],"lieux":[{"id":"z1","lieu":"paris","symbole":"point","nom":"Paris"},{"id":"z2","lieu":"new-york","symbole":"point","nom":"New York"}],"traits":[{"id":"z3","points":["paris",[-17.7,52.1],[-39,51.6],[-58.3,47.5],"new-york"],"style":"fleche","teinte":"violet","epaisseur":2,"etiquette":"Trajet A"},{"id":"z4","points":["paris",[-12.9,47.3],[-28.2,45.7],[-43.5,44.1],[-58.7,42.4],"new-york"],"style":"pointilles","teinte":"turquoise","epaisseur":2,"etiquette":"Trajet B"}]},{"id":"longueurs","type":"tableau","titre":"Longueurs des trajets","colonnes":["Trajet","Longueur"],"lignes":[["Trajet A","5 840 km"],["Trajet B","6 080 km"]],"enteteLignes":true,"source":"Valeurs arrondies"}],"questions":[{"enonce":"Touche le trajet le plus court des deux, d’après le tableau des longueurs.","aide":"Compare les longueurs, puis repère le trajet correspondant sur la carte.","type":"zone","document":"carte","multiple":false},{"enonce":"Que représente le trajet A, celui qui paraît « remonter vers le nord » ?","aide":"Le plus court chemin à la surface d’une sphère suit un grand cercle.","type":"choix","options":[{"id":"a","texte":"Un trajet de même longueur que le B, dessiné autrement sur la carte"},{"id":"b","texte":"Un détour sans intérêt qui évite les turbulences et allonge la durée du vol"},{"id":"c","texte":"La loxodromie : un trajet à cap constant, qui paraît courbe sur la carte"},{"id":"d","texte":"L’orthodromie : un arc de grand cercle, plus court malgré sa courbure apparente"}],"multiple":false},{"enonce":"Quelle distance l’orthodromie fait-elle économiser par rapport à la loxodromie, en km ?","aide":"Soustrais les deux longueurs.","type":"nombre","unite":"km"},{"enonce":"À 900 km/h, combien de minutes de vol cette économie représente-t-elle ?","aide":"Durée en heures = 240 ÷ 900 ; multiplie par 60.","type":"nombre","unite":"min"},{"enonce":"Pourquoi un trajet à cap constant (la loxodromie) reste-t-il utilisé malgré tout ?","aide":"Un navigateur sans GPS doit pouvoir le suivre avec une boussole.","type":"choix","options":[{"id":"a","texte":"Il est plus simple à suivre : on garde la même direction sur la boussole"},{"id":"b","texte":"Il est toujours plus court que l’arc de grand cercle sur une longue distance"},{"id":"c","texte":"Il n’existe aucun autre trajet possible pour relier deux continents"},{"id":"d","texte":"Il évite que l’avion ne traverse le méridien de Greenwich pendant le vol"}],"multiple":false}]}$ex$::jsonb,
