  ('b827458d-1d1b-5c5e-a7ee-249c0c075c8d'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Trois siècles de datations de la Terre","competence":"se-reperer-temps","situation":"Pour savoir quel âge a la Terre, des savants successifs ont proposé des réponses très différentes. Elsa range leurs travaux sur une frise.","documents":[{"id":"frise","type":"frise","titre":"L’âge de la Terre, de Ussher à Patterson","debut":1600,"fin":2000,"pas":50,"periodes":[],"evenements":[{"id":"z1","date":1650,"nom":"Ussher"},{"id":"z2","date":1778,"nom":"Buffon"},{"id":"z3","date":1862,"nom":"Kelvin"},{"id":"z4","date":1896,"nom":"Becquerel"},{"id":"z5","date":1953,"nom":"Patterson"}]}],"questions":[{"enonce":"Touche l’étape où l’on date des météorites par la méthode uranium-plomb et où l’on obtient 4,55 milliards d’années.","aide":"C’est la plus récente de la frise.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent l’estimation de Buffon de celle de Patterson ?","aide":"Soustrais la date de Buffon de celle de Patterson.","type":"nombre","unite":"ans"},{"enonce":"Associe chaque savant à sa méthode.","aide":"Les deux méthodes les plus anciennes ne sont pas des mesures sur la Terre elle-même.","type":"association","gauche":[{"id":"g0","texte":"Ussher"},{"id":"g1","texte":"Buffon"},{"id":"g2","texte":"Kelvin"},{"id":"g3","texte":"Patterson"}],"droite":[{"id":"d0","texte":"Thermodynamique du refroidissement"},{"id":"d1","texte":"Addition des générations bibliques"},{"id":"d2","texte":"Datation uranium-plomb de météorites"},{"id":"d3","texte":"Refroidissement de boulets de fer"}]}]}$ex$::jsonb,
