  ('b827458d-1d1b-5c5e-a7ee-249c0c075c8d'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Kelvin s’est-il trompé ?","competence":"analyser-texte","situation":"En 1862, lord Kelvin calcule l’âge de la Terre avec la thermodynamique : un raisonnement rigoureux, mais qui s’appuie sur des hypothèses. Zoé examine ce qui a mal tourné.","documents":[{"id":"raisonnement","type":"texte","genre":"article","titre":"Le raisonnement de Kelvin","blocs":["Kelvin part d’une Terre née très chaude, qui se refroidit depuis. Il suppose que le globe ne possède aucune source de chaleur interne, et que son manteau reste immobile.","Avec ces hypothèses, son calcul donne un âge compris entre 20 et 100 millions d’années."],"source":"Texte écrit pour l’exercice, d’après l’histoire des sciences"},{"id":"estimations","type":"tableau","titre":"Quelques estimations","colonnes":["Auteur","Estimation"],"lignes":[["Buffon, 1778","75 000 ans"],["Kelvin, 1862","20 à 100 millions d’années"],["Patterson, 1953","4 550 millions d’années"]],"enteteLignes":true,"source":"Valeurs arrondies"}],"questions":[{"enonce":"Touche l’hypothèse de Kelvin que la découverte de la radioactivité va rendre fausse.","aide":"La radioactivité chauffe l’intérieur du globe en permanence.","type":"zone","document":"raisonnement","multiple":true},{"enonce":"Même avec sa valeur la plus haute (100 millions d’années), de combien de fois Kelvin sous-estime-t-il l’âge de 4 550 millions d’années ? (arrondi à l’unité)","aide":"Divise 4 550 par 100.","type":"nombre"},{"enonce":"Même question pour Buffon (75 000 ans) : par combien l’âge réel est-il plus grand ? (arrondi à la dizaine de milliers)","aide":"Convertis 4 550 millions en années (4,55 × 10⁹), puis divise par 75 000.","type":"nombre"},{"enonce":"Touche l’estimation la plus proche de l’âge admis aujourd’hui (4,54 milliards d’années).","aide":"L’âge admis se compte en milliards d’années.","type":"zone","document":"estimations","multiple":false},{"enonce":"Quelle leçon tirer de l’erreur de Kelvin ?","aide":"Le calcul de Kelvin était juste : relis ses hypothèses.","type":"choix","options":[{"id":"a","texte":"Kelvin a fait une erreur de calcul qu’un autre savant a corrigée"},{"id":"b","texte":"Les savants du XIXe siècle ne cherchaient pas à dater la Terre"},{"id":"c","texte":"Un calcul de thermodynamique est toujours moins fiable qu’une observation"},{"id":"d","texte":"Un raisonnement rigoureux peut être faussé par une hypothèse manquante"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m19","m20","m21","m22","m23"]},"explication":"Kelvin ignorait toute **source de chaleur interne** : or la radioactivité, découverte par Becquerel en 1896, chauffe l’intérieur de la Terre."},{"cle":{"type":"nombre","valeur":46,"tolerance":1},"affichage":"46","explication":"4 550 ÷ 100 = 45,5 : il sous-estime d’un facteur **environ 46** au mieux."},{"cle":{"type":"nombre","valeur":60000,"tolerance":1000},"affichage":"60 000","explication":"4,55 × 10⁹ ÷ 75 000 ≈ **60 000** : de Buffon à aujourd’hui, l’estimation est multipliée par soixante mille."},{"cle":{"type":"zone","ids":["r2c1"]},"explication":"C’est celle de **Patterson** : 4 550 millions d’années, soit 4,55 milliards."},{"cle":{"type":"choix","ids":["d"]},"explication":"Son calcul était **correct** mais l’hypothèse « aucune source de chaleur interne » était fausse : une **hypothèse manquante** suffit à fausser un raisonnement rigoureux."}]$ex$::jsonb),
